INSERT INTO assessments (id,lesson_id,kind,title,rubric,source_page,source_note) VALUES (12,6,'post','Describe & Draw · post-assessment','LESSON 6: DESCRIBE AND DRAW

   (Show children a picture; they will describe it so someone else can draw it)

