INSERT INTO assessments (id,lesson_id,kind,title,rubric,source_page,source_note) VALUES (24,12,'post','Tongue Twisters · post-assessment','LESSON 11: USING TONGUE TWISTERS

 POST-TEST (5 items)

 Assesses ability to say tongue twisters clearly and with better pace.

 1. “Say ‘Red lorry, yellow lorry’ two times in a row—speak clearly, not too

 fast.”

 2. “Say ‘She sells seashells by the seashore’ once—make sure I can hear

 every word.”

 3. “Say ‘Peter Piper picked a peck of pickled peppers’ slowly, then a little

 faster (still clear!).”

 4. “Say ‘Six sick sheep shepherds’ sheep’ two times—don’t mix up

 the words.”

 5. “Say ‘How much wood would a woodchuck chuck?’ once—speak with a

 steady pace.”


                                                        Needs

   Criteria      Excellent     Good (3pts)    Satisfactory  Improvement

                    (4pts)                            (2pts)             (1pt)

              Pronounces              Some       Many

                   all words     Most correct    mispronunciat  mispronunciation

Pronunciation  correctly      pronunciation   ions but still    s; hard to follow

              (even at                         clear

               speed)

              Says the      Says it

              tongue        smoothly      Says it with    Stumbles

                 twister        once, with 1     2- 3 pauses    heavily or can’t

Fluency       smoothly 2+   pause                              finish

               times

               Tries           Tries willingly,

Effort &        enthusiastic   mostly          Tries but is    Reluctant to try

Confidence      ally, speaks   loud            quiet/hesitant  or gives up

                loudly',94,'The printed post-test headings reverse Lessons 11 and 12. Mapped by competency; original page is preserved.');
