INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (147,4,NULL,'learn',12,'Describe It! Share It!','group','Work with your teacher or partner. Record what you did; your teacher will review your work.','One student looks at the picture and thinks of 2-3 describing words for it. They say the describing words aloud and their partner guesses what’s in the picture. Pairs switch roles after 5 minutes.',NULL,'[]','One student looks at the picture and thinks of 2-3 describing words for it. They say the describing words aloud and their partner guesses what’s in the picture. Pairs switch roles after 5 minutes.',NULL,10,59,'One student looks at the picture and thinks of 2-3 describing words for it. They say the describing words aloud and their partner guesses what’s in the picture. Pairs switch roles after 5 minutes.');
