INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (154,5,NULL,'learn',7,'Picture Card Pack','group','Work with your teacher or partner. Record what you did; your teacher will review your work.','One student picks a picture from the pack and shares their thoughts using at least 2 sentence starters. The other students listen, then one peer asks a follow-up question. Everyone in the group takes a turn picking a picture and sharing.','assets/module/page-023.jpg','["assets/module/page-023.jpg"]','One student picks a picture from the pack and shares their thoughts using at least 2 sentence starters. The other students listen, then one peer asks a follow-up question. Everyone in the group takes a turn picking a picture and sharing.',NULL,10,23,'One student picks a picture from the pack and shares their thoughts using at least 2 sentence starters. The other students listen, then one peer asks a follow-up question. Everyone in the group takes a turn picking a picture and sharing.');
