INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (158,6,NULL,'learn',2,'Listen and draw','drawing','Work with your teacher or partner. Record what you did; your teacher will review your work.','First, there’s a big, green tree branch in the middle. On top of the branch, there’s a small, red bird with a yellow beak. Next to the bird, there’s a bright yellow flower with five petals. The sky behind is light blue.',NULL,'[]','First, there’s a big, green tree branch in the middle. On top of the branch, there’s a small, red bird with a yellow beak. Next to the bird, there’s a bright yellow flower with five petals. The sky behind is light blue.',NULL,10,64,'First, there’s a big, green tree branch in the middle. On top of the branch, there’s a small, red bird with a yellow beak. Next to the bird, there’s a bright yellow flower with five petals. The sky behind is light blue.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (159,6,NULL,'learn',3,'Check and discuss','open','Work with your teacher. Share your answer aloud, then type it or use the microphone. Your teacher will review your work.','What details helped you draw it right?','assets/module/image-215.jpeg','["assets/module/image-215.jpeg"]','What details helped you draw it right?',NULL,10,64,'What details helped you draw it right?');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (160,6,NULL,'learn',4,'Talk about details','open','Work with your teacher. Share your answer aloud, then type it or use the microphone. Your teacher will review your work.','What would happen if I forgot to say ‘small’ about the bird? Or ‘next to the bird’ about the flower?',NULL,'[]','What would happen if I forgot to say ‘small’ about the bird? Or ‘next to the bird’ about the flower?',NULL,10,64,'What would happen if I forgot to say ‘small’ about the bird? Or ‘next to the bird’ about the flower?');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (161,6,NULL,'learn',5,'Talk about details','open','Work with your teacher. Share your answer aloud, then type it or use the microphone. Your teacher will review your work.','Why is it important to describe things in order (e.g., ‘first the branch, then the bird’)?',NULL,'[]','Why is it important to describe things in order (e.g., ‘first the branch, then the bird’)?',NULL,10,64,'Why is it important to describe things in order (e.g., ‘first the branch, then the bird’)?');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (162,6,NULL,'learn',6,'Pair Describe and Draw','drawing','Work with your teacher or partner. Record what you did; your teacher will review your work.','The Describer looks at their picture and describes it using key details and the visual aid words. The Drawer listens carefully and draws what they hear—they can ask clarifying questions. After 5 minutes, have pairs switch roles with a new secret picture.','assets/module/image-222.jpeg','["assets/module/image-222.jpeg", "assets/module/image-223.jpeg", "assets/module/image-224.jpeg", "assets/module/image-225.jpeg", "assets/module/image-226.jpeg"]','The Describer looks at their picture and describes it using key details and the visual aid words. The Drawer listens carefully and draws what they hear—they can ask clarifying questions. After 5 minutes, have pairs switch roles with a new secret picture.',NULL,10,65,'The Describer looks at their picture and describes it using key details and the visual aid words. The Drawer listens carefully and draws what they hear—they can ask clarifying questions. After 5 minutes, have pairs switch roles with a new secret picture.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (163,7,NULL,'learn',1,'Guess the Next Picture','open','Work with your teacher. Share your answer aloud, then type it or use the microphone. Your teacher will review your work.','What do you see in this picture? What do you think will happen next?','assets/module/image-227.jpeg','["assets/module/image-227.jpeg", "assets/module/image-228.jpeg"]','What do you see in this picture? What do you think will happen next?',NULL,10,66,'What do you see in this picture? What do you think will happen next?');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (164,7,NULL,'learn',2,'Picture Story Chain','reading','Work with your teacher. Share your answer aloud, then type it or use the microphone. Your teacher will review your work.','Once upon a time, there was a little cat named Mimi. She woke up early in her cozy bed. Mimi jumped out of bed and walked outside to the garden.','assets/module/image-227.jpeg','["assets/module/image-227.jpeg", "assets/module/image-228.jpeg", "assets/module/image-229.jpeg", "assets/module/image-230.jpeg", "assets/module/image-231.jpeg", "assets/module/image-232.jpeg"]','Once upon a time, there was a little cat named Mimi. She woke up early in her cozy bed. Mimi jumped out of bed and walked outside to the garden.',NULL,10,67,'Once upon a time, there was a little cat named Mimi. She woke up early in her cozy bed. Mimi jumped out of bed and walked outside to the garden.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (165,7,NULL,'learn',3,'Group Picture Story Chain','group','Work with your teacher or partner. Record what you did; your teacher will review your work.','The first student looks at the first picture and says one sentence. The next student looks at the second picture and says a sentence that connects to the first. Continue until all pictures are used and the story has an ending. One student from each group will share the complete story with the class.','assets/module/page-068.jpg','["assets/module/page-068.jpg"]','The first student looks at the first picture and says one sentence. The next student looks at the second picture and says a sentence that connects to the first. Continue until all pictures are used and the story has an ending. One student from each group will share the complete story with the class.',NULL,10,68,'The first student looks at the first picture and says one sentence. The next student looks at the second picture and says a sentence that connects to the first. Continue until all pictures are used and the story has an ending. One student from each group will share the complete story with the class.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (166,7,NULL,'learn',4,'Group Picture Story Chain','group','Work with your teacher or partner. Record what you did; your teacher will review your work.','The first student looks at the first picture and says one sentence. The next student looks at the second picture and says a sentence that connects to the first. Continue until all pictures are used and the story has an ending. One student from each group will share the complete story with the class.','assets/module/page-069.jpg','["assets/module/page-069.jpg"]','The first student looks at the first picture and says one sentence. The next student looks at the second picture and says a sentence that connects to the first. Continue until all pictures are used and the story has an ending. One student from each group will share the complete story with the class.',NULL,10,69,'The first student looks at the first picture and says one sentence. The next student looks at the second picture and says a sentence that connects to the first. Continue until all pictures are used and the story has an ending. One student from each group will share the complete story with the class.');
