INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (204,12,NULL,'learn',7,'Tongue Twister Game','group','Work with your teacher or partner. Record what you did; your teacher will review your work.','In small groups, students pick a tongue twister. Say it slowly, then fast. Friends give a thumbs up if they hear the sounds clearly! Add fun: Hop or clap while saying it!','assets/module/image-289.jpeg','["assets/module/image-289.jpeg", "assets/module/image-290.jpeg", "assets/module/image-291.jpeg"]','In small groups, students pick a tongue twister. Say it slowly, then fast. Friends give a thumbs up if they hear the sounds clearly! Add fun: Hop or clap while saying it!',NULL,10,84,'In small groups, students pick a tongue twister. Say it slowly, then fast. Friends give a thumbs up if they hear the sounds clearly! Add fun: Hop or clap while saying it!');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (205,1,NULL,'learn',8,'Teacher-guided lesson checklist','reference','With your teacher, check all lesson procedures, evaluation, and home practice in the official guide. Your teacher confirms completion using the original checklist.','39 LESSON PLAN 1: ORAL LANGUAGE – TALKING ABOUT ONESELF AND ONE’S FAMILY I. OBJECTIVES At the end of the 45-minute lesson, the students will be able to: 1. Share at least 3 key details about oneself (name, age, favorite activity) using clear voice and proper pronunciation; 2. Talk about 2-3 family members and one thing they like to do together; 3. Maintain eye contact with their audience when speaking. II. SUBJECT MATTER Topic: Sharing Information About Oneself and One’s Family References: Adapted from elementary oral communication curricula and early childhood language development resources Materials: Visual aid (chart) with sentence starters: "My name is…", "I am years old…", "My family has…", "We like to…" Picture cards (e.g., of a child, parents, siblings, toys, activities like playing, eating) "About Me" worksheet (simple, with spaces for drawing and writing key details) Evaluation checklist III. PROCEDURE 1. PREPARATORY ACTIVITIES Warm-Up Lead a "Hello Circle" – students stand in a circle, take turns saying "Hello, my name is [name]" while waving to the class. Encourage them to speak loudly enough for everyone to hear. 40 Motivation Show a colorful picture of a happy family doing an activity (e.g., picnicking). Ask: "Who do you see in this picture?" and "What do you like to do with your own family?" Let 2-3 students share a quick thought to get them excited to talk more. 2. DEVELOPMENTAL ACTIVITIES Introduce Key Details: Display the visual aid with sentence starters. Explain that when we talk about ourselves and our family, we can use these sentences to make our ideas clear. Modeling: Share your own example in simple terms: "Hi, my name is [Teacher’s Name]. I am [age]. My favorite activity is reading. My family has [2 people] – my mom and dad. We like to cook together on weekends!" Use picture cards to point to each detail as you speak. Practice Sentence Starters: Have the class repeat the sentence starters together 2-3 times to build confidence. 3. GUIDED PRACTICE Pair-and-Share Activity: Divide students into pairs. Give each pair a set of picture cards to use as clues. 1. Student A uses the sentence starters to share about themselves and their family. 41 2. Student B listens, then shares their own information. 3. Circulate around pairs to support: remind them to speak clearly, make eye contact, and use the picture cards if they get stuck. After 8 minutes, ask 2-3 volunteer pairs to share one thing they learned about each other with the class. IV. EVALUATION Use an informal checklist to assess each student during pair-and-share: 1 2 3 4 Pupil mentioned Pupil mentioned Pupil mentioned Pupil mentioned only his name 2 – 3 details 4 details about 5 or more details about himself himself about himself V. AGREEMENT For homework, students will: Talk to one family member about their favorite activity. Draw a picture of themselves and that family member doing that activity. Be ready to share what they learned with the class in our next lesson.','assets/module/page-047.jpg','["assets/module/page-047.jpg", "assets/module/page-048.jpg", "assets/module/page-049.jpg"]','39 LESSON PLAN 1: ORAL LANGUAGE – TALKING ABOUT ONESELF AND ONE’S FAMILY I. OBJECTIVES At the end of the 45-minute lesson, the students will be able to: 1. Share at least 3 key details about oneself (name, age, favorite activity) using clear voice and proper pronunciation; 2. Talk about 2-3 family members and one thing they like to do together; 3. Maintain eye contact with their audience when speaking. II. SUBJECT MATTER Topic: Sharing Information About Oneself and One’s Family References: Adapted from elementary oral communication curricula and early childhood language development resources Materials: Visual aid (chart) with sentence starters: "My name is…", "I am years old…", "My family has…", "We like to…" Picture cards (e.g., of a child, parents, siblings, toys, activities like playing, eating) "About Me" worksheet (simple, with spaces for drawing and writing key details) Evaluation checklist III. PROCEDURE 1. PREPARATORY ACTIVITIES Warm-Up Lead a "Hello Circle" – students stand in a circle, take turns saying "Hello, my name is [name]" while waving to the class. Encourage them to speak loudly enough for everyone to hear. 40 Motivation Show a colorful picture of a happy family doing an activity (e.g., picnicking). Ask: "Who do you see in this picture?" and "What do you like to do with your own family?" Let 2-3 students share a quick thought to get them excited to talk more. 2. DEVELOPMENTAL ACTIVITIES Introduce Key Details: Display the visual aid with sentence starters. Explain that when we talk about ourselves and our family, we can use these sentences to make our ideas clear. Modeling: Share your own example in simple terms: "Hi, my name is [Teacher’s Name]. I am [age]. My favorite activity is reading. My family has [2 people] – my mom and dad. We like to cook together on weekends!" Use picture cards to point to each detail as you speak. Practice Sentence Starters: Have the class repeat the sentence starters together 2-3 times to build confidence. 3. GUIDED PRACTICE Pair-and-Share Activity: Divide students into pairs. Give each pair a set of picture cards to use as clues. 1. Student A uses the sentence starters to share about themselves and their family. 41 2. Student B listens, then shares their own information. 3. Circulate around pairs to support: remind them to speak clearly, make eye contact, and use the picture cards if they get stuck. After 8 minutes, ask 2-3 volunteer pairs to share one thing they learned about each other with the class. IV. EVALUATION Use an informal checklist to assess each student during pair-and-share: 1 2 3 4 Pupil mentioned Pupil mentioned Pupil mentioned Pupil mentioned only his name 2 – 3 details 4 details about 5 or more details about himself himself about himself V. AGREEMENT For homework, students will: Talk to one family member about their favorite activity. Draw a picture of themselves and that family member doing that activity. Be ready to share what they learned with the class in our next lesson.',NULL,10,47,'39 LESSON PLAN 1: ORAL LANGUAGE – TALKING ABOUT ONESELF AND ONE’S FAMILY I. OBJECTIVES At the end of the 45-minute lesson, the students will be able to: 1. Share at least 3 key details about oneself (name, age, favorite activity) using clear voice and proper pronunciation; 2. Talk about 2-3 family members and one thing they like to do together; 3. Maintain eye contact with their audience when speaking. II. SUBJECT MATTER Topic: Sharing Information About Oneself and One’s Family References: Adapted from elementary oral communication curricula and early childhood language development resources Materials: Visual aid (chart) with sentence starters: "My name is…", "I am years old…", "My family has…", "We like to…" Picture cards (e.g., of a child, parents, siblings, toys, activities like playing, eating) "About Me" worksheet (simple, with spaces for drawing and writing key details) Evaluation checklist III. PROCEDURE 1. PREPARATORY ACTIVITIES Warm-Up Lead a "Hello Circle" – students stand in a circle, take turns saying "Hello, my name is [name]" while waving to the class. Encourage them to speak loudly enough for everyone to hear. 40 Motivation Show a colorful picture of a happy family doing an activity (e.g., picnicking). Ask: "Who do you see in this picture?" and "What do you like to do with your own family?" Let 2-3 students share a quick thought to get them excited to talk more. 2. DEVELOPMENTAL ACTIVITIES Introduce Key Details: Display the visual aid with sentence starters. Explain that when we talk about ourselves and our family, we can use these sentences to make our ideas clear. Modeling: Share your own example in simple terms: "Hi, my name is [Teacher’s Name]. I am [age]. My favorite activity is reading. My family has [2 people] – my mom and dad. We like to cook together on weekends!" Use picture cards to point to each detail as you speak. Practice Sentence Starters: Have the class repeat the sentence starters together 2-3 times to build confidence. 3. GUIDED PRACTICE Pair-and-Share Activity: Divide students into pairs. Give each pair a set of picture cards to use as clues. 1. Student A uses the sentence starters to share about themselves and their family. 41 2. Student B listens, then shares their own information. 3. Circulate around pairs to support: remind them to speak clearly, make eye contact, and use the picture cards if they get stuck. After 8 minutes, ask 2-3 volunteer pairs to share one thing they learned about each other with the class. IV. EVALUATION Use an informal checklist to assess each student during pair-and-share: 1 2 3 4 Pupil mentioned Pupil mentioned Pupil mentioned Pupil mentioned only his name 2 – 3 details 4 details about 5 or more details about himself himself about himself V. AGREEMENT For homework, students will: Talk to one family member about their favorite activity. Draw a picture of themselves and that family member doing that activity. Be ready to share what they learned with the class in our next lesson.');
