upil executed Pupil executed to do what has wrongly what incompletely accurately what been said. has been said. what has been has been said. said Additional Intervention Material Instructions: You ask your younger sister to keep her toys away. What will you say? Give her at least two instructions. Rubrics 1 2 3 4 Pupil give Pupil gave 1 Pupil gave 2 Pupil gave incomplete/inaccurate accurate accurate and more than 2 direction. direction. complete accurate and directions. complete directions.',NULL,10,35,'28 Additional Intervention Material Learning Competency: Talk about oneself and one’s family Instruction: Tell me something about yourself. Rubrics 1 2 3 4 Pupil mentioned Pupil mentioned Pupil mentioned Pupil mentioned only his name 2 – 3 details 4 details about 5 or more details about himself himself about himself Additional Intervention Material Learning Competency: Follow one to two steps directions Instructions: 1. Go to the door and close it. 2. Run back to your seat. Rubrics 1 2 3 4 Pupil attempted Pupil executed Pupil executed Pupil executed to do what has wrongly what incompletely accurately what been said. has been said. what has been has been said. said Additional Intervention Material Instructions: You ask your younger sister to keep her toys away. What will you say? Give her at least two instructions. Rubrics 1 2 3 4 Pupil give Pupil gave 1 Pupil gave 2 Pupil gave incomplete/inaccurate accurate accurate and more than 2 direction. direction. complete accurate and directions. complete directions.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (207,2,NULL,'learn',14,'Teacher-guided lesson checklist','reference','With your teacher, check all lesson procedures, evaluation, and home practice in the official guide. Your teacher confirms completion using the original checklist.','42 LESSON PLAN 2: ORAL LANGUAGE – FOLLOWING 1-TO-2-STEP ORAL DIRECTIONS I. OBJECTIVES At the end of the 45-minute lesson, the students will be able to: 1. Listen carefully to follow 1-step and 2-step oral directions accurately; 2. Repeat the directions in their own words before completing them; 3. Perform the actions in the correct order. II. SUBJECT MATTER Topic: Following 1-to-2-Step Oral Directions References: Adapted from elementary oral language curricula and motor skill development resources Materials: Visual aid (chart) with action words and pictures: go, close, run, pick up, sit, give Simple props (classroom items): door, chair, book, pencil, toy "Mission Card" set (with pre-written 1-2 step directions) Informal evaluation checklist III. PROCEDURE 1. PREPARATORY ACTIVITIES Warm-Up (5 minutes): Lead the class in an "Action Song" (e.g., "Head, Shoulders, Knees, and Toes") – have them follow along with your oral cues to practice listening and moving. Motivation (5 minutes): Say: "Today, you’re all secret agents on a special mission! To complete the mission, you need to listen very carefully to my directions. If you follow them right, you’ll get a ‘Secret Agent Badge’ at the end!" Show a fun, hand-drawn badge to build excitement. 43 2. DEVELOPMENTAL ACTIVITIES Introduce 1-Step Directions: Display the visual aid with action words. Give a simple 1-step direction (e.g., "Go to the chair") and do it yourself to model. Ask 3-4 students to try one at a time, reminding them to listen first. Introduce 2-Step Directions: Explain that 2-step directions have two actions to do in order. Model with: "Go to the door, then close it." Point to the visual cards for "go" and "close" as you speak. Have students repeat the direction back to you before trying it. Practice Repeating Directions: Teach them the phrase, "Let me say that back: [repeat direction]" to make sure they understand. Practice with 2-3 more 2-step directions (e.g., "Pick up the book, then give it to me"). 3. ANALYSIS / DISCUSSION (5 minutes) Ask: "When I said ‘Go to the door and close it,’ what was the first thing you did? The second thing?" (Let students share to confirm order.) Follow up: "Why is it important to listen to all the direction before you start?" (e.g., "So, you don’t forget the second step," "So, you do it right") Remind them: "Repeating the direction back helps you make sure you heard it correctly!"ss 4. GUIDED PRACTICE (10 minutes) Secret Agent Mission Trail: Set up 3 simple stations around the classroom. Give each small group (4-5 students) a "Mission Card" with a 1 or 2-step direction for each station. Station 1: "Go to the window and tap it twice." Station 2: "Pick up one pencil and put it on the table." Station 3: "Run to the whiteboard, then sit down in your chair." Each student takes a turn leading their group through a station: they read the mission card aloud, their group repeats it back, then everyone does the action together. Circulate to support and remind students to follow order and speak clearly 44 IV. EVALUATION (5 minutes) Give 1-2 steps directions orally. Rate the learner’s performance based on the rubrics. Rubrics 1 2 3 4 Pupil attempted Pupil executed Pupil executed Pupil executed to do what has wrongly what incompletely accurately what been said. has been said. what has been has been said. said V. AGREEMENT For homework, students will: Be a "family helper" by following one 2-step direction from a parent or guardian (e.g., "Set one plate on the table and put a fork next to it"). Ask their family member to give them a "thumbs up" if they did it right. Share what direction they followed with the class in our next lesson.','assets/module/page-050.jpg','["assets/module/page-050.jpg", "assets/module/page-051.jpg", "assets/module/page-052.jpg"]','42 LESSON PLAN 2: ORAL LANGUAGE – FOLLOWING 1-TO-2-STEP ORAL DIRECTIONS I. OBJECTIVES At the end of the 45-minute lesson, the students will be able to: 1. Listen carefully to follow 1-step and 2-step oral directions accurately; 2. Repeat the directions in their own words before completing them; 3. Perform the actions in the correct order. II. SUBJECT MATTER Topic: Following 1-to-2-Step Oral Directions References: Adapted from elementary oral language curricula and motor skill development resources Materials: Visual aid (chart) with action words and pictures: go, close, run, pick up, sit, give Simple props (classroom items): door, chair, book, pencil, toy "Mission Card" set (with pre-written 1-2 step directions) Informal evaluation checklist III. PROCEDURE 1. PREPARATORY ACTIVITIES Warm-Up (5 minutes): Lead the class in an "Action Song" (e.g., "Head, Shoulders, Knees, and Toes") – have them follow along with your oral cues to practice listening and moving. Motivation (5 minutes): Say: "Today, you’re all secret agents on a special mission! To complete the mission, you need to listen very carefully to my directions. If you follow them right, you’ll get a ‘Secret Agent Badge’ at the end!" Show a fun, hand-drawn badge to build excitement. 43 2. DEVELOPMENTAL ACTIVITIES Introduce 1-Step Directions: Display the visual aid with action words. Give a simple 1-step direction (e.g., "Go to the chair") and do it yourself to model. Ask 3-4 students to try one at a time, reminding them to listen first. Introduce 2-Step Directions: Explain that 2-step directions have two actions to do in order. Model with: "Go to the door, then close it." Point to the visual cards for "go" and "close" as you speak. Have students repeat the direction back to you before trying it. Practice Repeating Directions: Teach them the phrase, "Let me say that back: [repeat direction]" to make sure they understand. Practice with 2-3 more 2-step directions (e.g., "Pick up the book, then give it to me"). 3. ANALYSIS / DISCUSSION (5 minutes) Ask: "When I said ‘Go to the door and close it,’ what was the first thing you did? The second thing?" (Let students share to confirm order.) Follow up: "Why is it important to listen to all the direction before you start?" (e.g., "So, you don’t forget the second step," "So, you do it right") Remind them: "Repeating the direction back helps you make sure you heard it correctly!"ss 4. GUIDED PRACTICE (10 minutes) Secret Agent Mission Trail: Set up 3 simple stations around the classroom. Give each small group (4-5 students) a "Mission Card" with a 1 or 2-step direction for each station. Station 1: "Go to the window and tap it twice." Station 2: "Pick up one pencil and put it on the table." Station 3: "Run to the whiteboard, then sit down in your chair." Each student takes a turn leading their group through a station: they read the mission card aloud, their group repeats it back, then everyone does the action together. Circulate to support and remind students to follow order and speak clearly 44 IV. EVALUATION (5 minutes) Give 1-2 steps directions orally. Rate the learner’s performance based on the rubrics. Rubrics 1 2 3 4 Pupil attempted Pupil executed Pupil executed Pupil executed to do what has wrongly what incompletely accurately what been said. has been said. what has been has been said. said V. AGREEMENT For homework, students will: Be a "family helper" by following one 2-step direction from a parent or guardian (e.g., "Set one plate on the table and put a fork next to it"). Ask their family member to give them a "thumbs up" if they did it right. Share what direction they followed with the class in our next lesson.',NULL,10,50,'42 LESSON PLAN 2: ORAL LANGUAGE – FOLLOWING 1-TO-2-STEP ORAL DIRECTIONS I. OBJECTIVES At