the first thing you did? The second thing?" (Let students share to confirm order.) Follow up: "Why is it important to listen to all the direction before you start?" (e.g., "So, you don’t forget the second step," "So, you do it right") Remind them: "Repeating the direction back helps you make sure you heard it correctly!"ss 4. GUIDED PRACTICE (10 minutes) Secret Agent Mission Trail: Set up 3 simple stations around the classroom. Give each small group (4-5 students) a "Mission Card" with a 1 or 2-step direction for each station. Station 1: "Go to the window and tap it twice." Station 2: "Pick up one pencil and put it on the table." Station 3: "Run to the whiteboard, then sit down in your chair." Each student takes a turn leading their group through a station: they read the mission card aloud, their group repeats it back, then everyone does the action together. Circulate to support and remind students to follow order and speak clearly 44 IV. EVALUATION (5 minutes) Give 1-2 steps directions orally. Rate the learner’s performance based on the rubrics. Rubrics 1 2 3 4 Pupil attempted Pupil executed Pupil executed Pupil executed to do what has wrongly what incompletely accurately what been said. has been said. what has been has been said. said V. AGREEMENT For homework, students will: Be a "family helper" by following one 2-step direction from a parent or guardian (e.g., "Set one plate on the table and put a fork next to it"). Ask their family member to give them a "thumbs up" if they did it right. Share what direction they followed with the class in our next lesson.');
