Pupil executed Pupil executed to do what has wrongly what incompletely accurately what been said. has been said. what has been has been said. said Additional Intervention Material Instructions: You ask your younger sister to keep her toys away. What will you say? Give her at least two instructions. Rubrics 1 2 3 4 Pupil give Pupil gave 1 Pupil gave 2 Pupil gave incomplete/inaccurate accurate accurate and more than 2 direction. direction. complete accurate and directions. complete directions.',NULL,10,35,'28 Additional Intervention Material Learning Competency: Talk about oneself and one’s family Instruction: Tell me something about yourself. Rubrics 1 2 3 4 Pupil mentioned Pupil mentioned Pupil mentioned Pupil mentioned only his name 2 – 3 details 4 details about 5 or more details about himself himself about himself Additional Intervention Material Learning Competency: Follow one to two steps directions Instructions: 1. Go to the door and close it. 2. Run back to your seat. Rubrics 1 2 3 4 Pupil attempted Pupil executed Pupil executed Pupil executed to do what has wrongly what incompletely accurately what been said. has been said. what has been has been said. said Additional Intervention Material Instructions: You ask your younger sister to keep her toys away. What will you say? Give her at least two instructions. Rubrics 1 2 3 4 Pupil give Pupil gave 1 Pupil gave 2 Pupil gave incomplete/inaccurate accurate accurate and more than 2 direction. direction. complete accurate and directions. complete directions.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (209,3,NULL,'learn',10,'Teacher-guided lesson checklist','reference','With your teacher, check all lesson procedures, evaluation, and home practice in the official guide. Your teacher confirms completion using the original checklist.','LESSON PLAN 3: ORAL LANGUAGE – GIVING AND FOLLOWING 1-TO-2- STEP ORAL DIRECTIONS IN DAILY SITUATIONS I. OBJECTIVE At the end of the 45-minute lesson, the students will be able to: 1. Give clear 1-2 step oral directions using polite language (e.g., "can you," "please"); 2. Follow 1-2 step directions given by a peer; 3. Identify 2 key elements of effective directions (clarity, order) and polite communication. II. SUBJECT MATTER Topic: Giving and Following 1-2-Step Directions (e.g., Asking a Sibling to Tidy Up Toys) References: Adapted from elementary oral communication curricula and social skills development resources 45 Materials: Visual aid (chart) with: Polite phrase starters: "Can you…?", "Please…", "Thank you!" Action words with pictures: keep away, put in, pick up, close Toy props (dolls, cars, blocks, a toy box) Scenario cards (e.g., "Your younger sister left toys on the floor", "Your brother left books on the couch") Informal evaluation checklist III. PROCEDURE 1. PREPARATORY ACTIVITIES Warm-Up (5 minutes): Lead a "Follow My Lead" game: Give 1-2 step directions (e.g., "Pick up one block and put it on your desk") and have the class do them together. This review following directions before moving to giving them. Motivation (5 minutes): Show a photo of a messy playroom with toys scattered. Ask: "Have you ever seen a room like this? If your younger sister made this mess, what would you say to ask her to clean it up?" Let 2-3 students share quick ideas, then say: "Today, we’ll learn to ask nicely with clear steps so she knows exactly what to do!" 2. DEVELOPMENTAL ACTIVITIES (15 minutes) Introduce Polite Directions: Display the visual aid with polite phrases. Explain that when asking someone to do something, we use kind words like "can you" and "please" to be respectful. 46 Model Giving 2-Step Directions: Use the toy props to act out the scenario: "Let’s pretend this doll is my younger sister, and these toys are on the floor. I’ll say: “‘Can you please keep your toys away and put them in the toy box?’" Point to the action pictures ("keep away," "put in") as you speak to show order. Practice Making Directions: Have the class repeat the model direction together. Then, guide them to make their own 2-step direction for the same scenario (e.g., "Can you pick up your cars and put them on the shelf?"). 3. ANALYSIS / DISCUSSION Ask: "What polite words did I use when asking my sister?" (Let students point to the visual aid.) Follow up: "What was the first step I asked her to do? The second step? Why is order important?" (e.g., "So, she doesn’t get confused," "So, she does everything needed"). Ask: "How do you think your sister would feel if you asked nicely vs. yelling?" (Emphasize that polite language helps others want to help.) 4. GUIDED PRACTICE Role-Play Activity: Divide students into pairs. Give each pair a scenario card and toy props. 1. One student plays the "older sibling" and gives a clear 2-step direction using polite language. 2. The other student plays the "younger sibling," listens, and follows the directions. 3. Pairs switch roles after 5 minutes. 47 Circulate around pairs to support: Remind them to use polite phrases, keep directions clear, and follow steps in order. Example scenario prompt for pairs: "Your younger sister left her dolls on the bed. What 2 things will you ask her to do?" IV. EVALUATION Use an informal checklist to assess each student during the role-play: Uses polite Gives clear Listens language (can 2-step directions carefully and Criteria you, please) in the correct follows peer’s when giving order directions directions accurately Excellent Good Satisfactory Note: Assess by observing each pair once. Give positive feedback like, "Great job asking nicely!" or "Perfect order of steps!" V. AGREEMENT For homework, students will: Find a time to give one 2-step direction to a family member (sibling, parent, or grandparent) using polite language (e.g., "Can you please pass the spoon and put it on my plate?"). Ask the family member if they understood the directions. Share what direction they gave and how it went with the class in our next lesson.','assets/module/page-052.jpg','["assets/module/page-052.jpg", "assets/module/page-053.jpg", "assets/module/page-054.jpg", "assets/module/page-055.jpg"]','LESSON PLAN 3: ORAL LANGUAGE – GIVING AND FOLLOWING 1-TO-2- STEP ORAL DIRECTIONS IN DAILY SITUATIONS I. OBJECTIVE At the end of the 45-minute lesson, the students will be able to: 1. Give clear 1-2 step oral directions using polite language (e.g., "can you," "please"); 2. Follow 1-2 step directions given by a peer; 3. Identify 2 key elements of effective directions (clarity, order) and polite communication. II. SUBJECT MATTER Topic: Giving and Following 1-2-Step Directions (e.g., Asking a Sibling to Tidy Up Toys) References: Adapted from elementary oral communication curricula and social skills development resources 45 Materials: Visual aid (chart) with: Polite phrase starters: "Can you…?", "Please…", "Thank you!" Action words with pictures: keep away, put in, pick up, close Toy props (dolls, cars, blocks, a toy box) Scenario cards (e.g., "Your younger sister left toys on the floor", "Your brother left books on the couch") Informal evaluation checklist III. PROCEDURE 1. PREPARATORY ACTIVITIES Warm-Up (5 minutes): Lead a "Follow My Lead" game: Give 1-2 step directions (e.g., "Pick up one block and put it on your desk") and have the class do them together. This review following directions before moving to giving them. Motivation (5 minutes): Show a photo of a messy playroom with toys scattered. Ask: "Have you ever seen a room like this? If your younger sister made this mess, what would you say to ask her to clean it up?" Let 2-3 students share quick ideas, then say: "Today, we’ll learn to ask nicely with clear steps so she knows exactly what to do!" 2. DEVELOPMENTAL ACTIVITIES (15 minutes) Introduce Polite Directions: Display the visual aid with polite phrases. Explain that when asking someone to do something, we use kind words like "can you" and "please" to be respectful. 46 Model Giving 2-Step Directions: Use the toy props to act out the scenario: "Let’s pretend this doll is my younger sister, and these toys are on the floor. I’ll say: “‘Can you please keep your toys away and put them in the toy box?’" Point to the action pictures ("keep away," "put in") as you speak to show order. Practice Making Directions: Have the class repeat the model direction together. Then, guide them to make their own 2-step direction for the same scenario (e.g., "Can you pick up your cars and put them on the shelf?"). 3. ANALYSIS / DISCUSSION Ask: "What polite words did I use when asking my sister?" (Let students point to the visual aid.) Follow up: "What was the first step I asked her to do? The second step? Why is order important?" (e.g., "So, she doesn’t get confused," "So, she does everything needed"). Ask: "How do you think your sister would feel if you asked nicely vs. yelling?" (Emphasize that polite language helps others want to help.) 4. GUIDED PRACTICE Role-Play Activity: Divide students into pairs. Give each pair a scenario card and toy props. 1. One student plays the "older sibling" and gives a clear 2-step direction using polite language. 2. The other student plays the "younger sibling," listens, and follows the directions. 3. Pairs switch roles after 5 minutes. 47 Circulate around pairs to support: Remind them to use polite phrases, keep directions clear, and follow steps in order. Example scenario prompt for pairs: "Your younger sister left her dolls on the bed. What 2 things will you ask her to do?" IV. EVALUATION Use an informal checklist to assess each student during the role-play: Uses polite Gives clear Listens language (can 2-step directions carefully and Criteria you, please) in the correct follows peer’s when giving order directions directions accurately Excellent Good Satisfactory Note: Assess by observing each pair once. Give positive feedback like, "Great job asking nicely!" or "Perfect order of steps!" V. AGREEMENT For homework, students will: Find a time to give one 2-step direction to a family member (sibling, parent, or grandparent) using polite language (e.g., "Can you please pass the spoon and put it on my plate?"). Ask the family member if they understood the directions. Share what direction they gave and how it went with the class in our next lesson.',NULL,10,52,'LESSON PLAN 3: ORAL LANGUAGE – GIVING AND FOLLOWING 1-TO-2- STEP ORAL DIRECTIONS IN DAILY SITUATIONS I. OBJECTIVE At the end of the 45-minute lesson, the students will be able to: 1. Give clear 1-2 step oral directions using polite language (e.g., "can you," "please"); 2. Follow 1-2 step directions given by a peer; 3. Identify 2 key elements of effective directions (clarity, order) and polite communication. II. SUBJECT MATTER Topic: Giving and Following 1-2-Step Directions (e.g., Asking a Sibling to Tidy Up Toys) References: Adapted from elementary oral communication curricula and social skills development resources 45 Materials: Visual aid (chart) with: Polite phrase starters: "Can you…?", "Please…", "Thank you!" Action words with pictures: keep away, put in, pick up, close Toy props (dolls, cars, blocks, a toy box) Scenario cards (e.g., "Your younger sister left toys on the floor", "Your brother left books on the couch") Informal evaluation checklist III. PROCEDURE 1. PREPARATORY ACTIVITIES Warm-Up (5 minutes): Lead a "Follow My Lead" game: Give 1-2 step directions (e.g., "Pick up one block and put it on your desk") and have the class do them together. This review following directions before moving to giving them. Motivation (5 minutes): Show a photo of a messy playroom with toys scattered. Ask: "Have you ever seen a room like this? If your younger sister made this mess, what would you say to ask her to clean it up?" Let 2-3 students share quick ideas, then say: "Today, we’ll learn to ask nicely with clear steps so she knows exactly what to do!" 2. DEVELOPMENTAL ACTIVITIES (15 minutes) Introduce Polite Directions: Display the visual aid with polite phrases. Explain that when asking someone to do something, we use kind words like "can you" and "please" to be respectful. 46 Model Giving 2-Step Directions: Use the toy props to act out the scenario: "Let’s pretend this doll is my younger sister, and these toys are on the floor. I’ll say: “‘Can you please keep your toys away and put them in the toy box?’" Point to the action pictures ("keep away," "put in") as you speak to show order. Practice Making Directions: Have the class repeat the model direction together. Then, guide them to make their own 2-step direction for the same scenario (e.g., "Can you pick up your cars and put them on the shelf?"). 3. ANALYSIS / DISCUSSION Ask: "What polite words did I use when asking my sister?" (Let students point to the visual aid.) Follow up: "What was the first step I asked her to do? The second step? Why is order important?" (e.g., "So, she doesn’t get confused," "So, she does everything needed"). Ask: "How do you think your sister would feel if you asked nicely vs. yelling?" (Emphasize that polite language helps others want to help.) 4. GUIDED PRACTICE Role-Play Activity: Divide students into pairs. Give each pair a scenario card and toy props. 1. One student plays the "older sibling" and gives a clear 2-step direction using polite language. 2. The other student plays the "younger sibling," listens, and follows the directions. 3. Pairs switch roles after 5 minutes. 47 Circulate around pairs to support: Remind them to use polite phrases, keep directions clear, and follow steps in order. Example scenario prompt for pairs: "Your younger sister left her dolls on the bed. What 2 things will you ask her to do?" IV. EVALUATION Use an informal checklist to assess each student during the role-play: Uses polite Gives clear Listens language (can 2-step directions carefully and Criteria you, please) in the correct follows peer’s when giving order directions directions accurately Excellent Good Satisfactory Note: Assess by observing each pair once. Give positive feedback like, "Great job asking nicely!" or "Perfect order of steps!" V. AGREEMENT For homework, students will: Find a time to give one 2-step direction to a family member (sibling, parent, or grandparent) using polite language (e.g., "Can you please pass the spoon and put it on my plate?"). Ask the family member if they understood the directions. Share what direction they gave and how it went with the class in our next lesson.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (210,3,NULL,'learn',11,'Additional intervention materials','reference','Use the original additional intervention material with your teacher. Your teacher will record which practice you completed.','28 Additional Intervention Material Learning Competency: Talk about oneself and one’s family Instruction: Tell me something about yourself. Rubrics 1 2 3 4 Pupil mentioned Pupil mentioned Pupil mentioned Pupil mentioned only his name 2 – 3 details 4 details about 5 or more details about himself himself about himself Additional Intervention Material Learning Competency: Follow one to two steps directions Instructions: 1. Go to the door and close it. 2. Run back to your seat. Rubrics 1 2 3 4 Pupil attempted Pupil executed Pupil executed Pupil executed to do what has wrongly what incompletely accurately what been said. has been said. what has been has been said. said Additional Intervention Material Instructions: You ask your younger sister to keep her toys away. What will you say? Give her at least two instructions. Rubrics 1 2 3 4 Pupil give Pupil gave 1 Pupil gave 2 Pupil gave incomplete/inaccurate accurate accurate and more than 2 direction. direction. complete accurate and directions. complete directions.','assets/module/page-035.jpg','["assets/module/page-035.jpg"]','28 Additional Intervention Material Learning Competency: Talk about oneself and one’s family Instruction: Tell me something about yourself. Rubrics 1 2 3 4 Pupil mentioned Pupil mentioned Pupil mentioned Pupil mentioned only his name 2 – 3 details 4 details about 5 or more details about himself himself about himself Additional Intervention Material Learning Competency: Follow one to two steps directions Instructions: 1. Go to the door and close it. 2. Run back to your seat. Rubrics 1 2 3 4 Pupil attempted Pupil executed Pupil executed Pupil executed to do what has wrongly what incompletely accurately what been said. has been said. what has been has been said. said Additional Intervention Material Instructions: You ask your younger sister to keep her toys away. What will you say? Give her at least two instructions. Rubrics 1 2 3 4 Pupil give Pupil gave 1 Pupil gave 2 Pupil gave incomplete/inaccurate accurate accurate and more than 2 direction. direction. complete accurate and directions. complete directions.',NULL,10,35,'28 Additional Intervention Material Learning Competency: Talk about oneself and one’s family Instruction: Tell me something about yourself. Rubrics 1 2 3 4 Pupil mentioned Pupil mentioned Pupil mentioned Pupil mentioned only his name 2 – 3 details 4 details about 5 or more details about himself himself about himself Additional Intervention Material Learning Competency: Follow one to two steps directions Instructions: 1. Go to the door and close it. 2. Run back to your seat. Rubrics 1 2 3 4 Pupil attempted Pupil executed Pupil executed Pupil executed to do what has wrongly what incompletely accurately what been said. has been said. what has been has been said. said Additional Intervention Material Instructions: You ask your younger sister to keep her toys away. What will you say? Give her at least two instructions. Rubrics 1 2 3 4 Pupil give Pupil gave 1 Pupil gave 2 Pupil gave incomplete/inaccurate accurate accurate and more than 2 direction. direction. complete accurate and directions. complete directions.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (211,4,NULL,'learn',13,'Teacher-guided lesson checklist','reference','With your teacher, check all lesson procedures, evaluation, and home practice in the official guide. Your teacher confirms completion using the original checklist.','48 LESSON PLAN 4: ORAL LANGUAGE – USING DESCRIBING WORDS FOR PEOPLE, OBJECTS, THINGS, AND PLACES I. OBJECTIVE At the end of the 45-minute lesson, the students will be able to: 1. Use describing words to talk about people, objects, things, and places. (color, shape, size, height, weight, length, distance, etc.) 2. Match describing words to the attributes of what they are talking about. II. SUBJECT MATTER Topic: Recognizing and Using Describing Words (Attributes: Color, Shape, Size, Height, Weight, Length, Distance) References: Adapted from elementary oral language curricula and vocabulary development resources Materials: Visual aid (chart) titled "My Describing Word Toolkit" – with words and pictures: red, round, big, tall, heavy, long, far, cozy Props with different attributes: colored blocks, toys (ball, box, car, doll), books (thick, thin), plants (tall, short), photos of places (sunny park, quiet room) "Describe It!" cards (with pictures of people, objects, or places) Informal evaluation checklist III. PROCEDURE 1. PREPARATORY ACTIVITIES Warm-Up (5 minutes): Lead a "Word Clue" game: Say, "I’m thinking of something in this room that’s red. Can you guess what it is?" Have students call out guesses, then reveal the object. Repeat with 3-4 more clues (e.g., "It’s round," "It’s big"). 49 Motivation (5 minutes): Show a plain drawing of a cat and a colorful, detailed drawing of the same cat. Ask: "Which drawing tells you more about the cat? Why?" Explain: "Today, we’ll learn about ‘describing words’ – these are like magic clues that help us tell others exactly what something looks like, feels like, or where it is!" 2. DEVELOPMENTAL ACTIVITIES Introduce Describing Words: Display the "Describing Word Toolkit" chart. Point to each word and its picture, and say: "These words describe attributes – what something is like. ‘Red’ is a color, ‘round’ is a shape, ‘big’ is a size, and ‘far’ is a distance." Have students repeat each word aloud. Describing words toolkit (see intervention materials) 1. Colors Red, blue, green, yellow, orange, purple, pink, black, white, brown 2. Sizes Big, small, tall, short, long, tiny, huge 3. Shapes Round, square, triangle, circle, flat 50 4. How things feel Soft, hard, smooth, rough, sticky, fuzzy, warm, cold 5. How things look Bright, dark, shiny, dull, clean, dirty, wet, dry 6. Feelings (for people/animals) Happy, sad, angry, scared, excited, sleepy, friendly 7. Numbers (to describe how many) One, two, three, many, few, some Model Using Describing Words: Pick up a red, round ball and say: "This is a red, round ball. It’s also small enough to hold in my hand." Then point to a tall plant: "This is a tall, green plant that’s near the window." Model for a person too: "My friend Lila has curly, brown hair and she is happy today." Practice Naming Attributes: Hold up different props (e.g., thick book, heavy toy car) and ask: "What describing words can we use for this?" Have students share ideas and match them to the chart. 3. ANALYSIS / DISCUSSION Ask: "Why do we use describing words when we talk?" (Let students share: "So others can picture what we’re talking about," "To be clear," "To make stories more fun"). Follow up: "Can we use more than one describing word for something? Let’s try with the box – is it square, blue, or both?" (Emphasize that we can combine words to give more details). Ask: "What describing words can we use for places, like a park?" (e.g., "sunny," "big," "busy"). 51 4. GUIDED PRACTICE "Describe It! Share It!" Activity: Divide students into pairs. Give each pair a "Describe It!" card with a picture (e.g., a cozy bedroom, a small yellow bird, a tall boy). 1. One student looks at the picture and thinks of 2-3 describing words for it. 2. They say the describing words aloud (e.g., "It’s cozy, quiet, and has a big bed") and their partner guesses what’s in the picture. 3. Pairs switch roles after 5 minutes. Circulate to support: Remind students to use words from the toolkit and match them to the picture’s attributes. IV. EVALUATION Use an informal checklist to assess each student during the pair activity: Recognizes Uses describing Matches and names at words to talk about describing Criteria least 4 people/objects/places words to the describing correct words attributes Excellent Good Satisfactory Note: Assess by listening to each pair’s descriptions. Give positive feedback like, "Great use of ‘cozy’ for the bedroom!" or "Perfect – ‘tall’ matches the boy!" V. AGREEMENT For homework, students will: 1. Pick one thing at home (a toy, a pet, a room) and think of 3 describing words for it. 2. Tell a family member about it using those words (e.g., "My dog is brown, fluffy, and small"). Be ready to share their description with the class in our next lesson.','assets/module/page-056.jpg','["assets/module/page-056.jpg", "assets/module/page-057.jpg", "assets/module/page-058.jpg", "assets/module/page-059.jpg"]','48 LESSON PLAN 4: ORAL LANGUAGE – USING DESCRIBING WORDS FOR PEOPLE, OBJECTS, THINGS, AND PLACES I. OBJECTIVE At the end of the 45-minute lesson, the students will be able to: 1. Use describing words to talk about people, objects, things, and places. (color, shape, size, height, weight, length, distance, etc.) 2. Match describing words to the attributes of what they are talking about. II. SUBJECT MATTER Topic: Recognizing and Using Describing Words (Attributes: Color, Shape, Size, Height, Weight, Length, Distance) References: Adapted from elementary oral language curricula and vocabulary development resources Materials: Visual aid (chart) titled