t: "This is a tall, green plant that’s near the window." Model for a person too: "My friend Lila has curly, brown hair and she is happy today." Practice Naming Attributes: Hold up different props (e.g., thick book, heavy toy car) and ask: "What describing words can we use for this?" Have students share ideas and match them to the chart. 3. ANALYSIS / DISCUSSION Ask: "Why do we use describing words when we talk?" (Let students share: "So others can picture what we’re talking about," "To be clear," "To make stories more fun"). Follow up: "Can we use more than one describing word for something? Let’s try with the box – is it square, blue, or both?" (Emphasize that we can combine words to give more details). Ask: "What describing words can we use for places, like a park?" (e.g., "sunny," "big," "busy"). 51 4. GUIDED PRACTICE "Describe It! Share It!" Activity: Divide students into pairs. Give each pair a "Describe It!" card with a picture (e.g., a cozy bedroom, a small yellow bird, a tall boy). 1. One student looks at the picture and thinks of 2-3 describing words for it. 2. They say the describing words aloud (e.g., "It’s cozy, quiet, and has a big bed") and their partner guesses what’s in the picture. 3. Pairs switch roles after 5 minutes. Circulate to support: Remind students to use words from the toolkit and match them to the picture’s attributes. IV. EVALUATION Use an informal checklist to assess each student during the pair activity: Recognizes Uses describing Matches and names at words to talk about describing Criteria least 4 people/objects/places words to the describing correct words attributes Excellent Good Satisfactory Note: Assess by listening to each pair’s descriptions. Give positive feedback like, "Great use of ‘cozy’ for the bedroom!" or "Perfect – ‘tall’ matches the boy!" V. AGREEMENT For homework, students will: 1. Pick one thing at home (a toy, a pet, a room) and think of 3 describing words for it. 2. Tell a family member about it using those words (e.g., "My dog is brown, fluffy, and small"). Be ready to share their description with the class in our next lesson.',NULL,10,56,'48 LESSON PLAN 4: ORAL LANGUAGE – USING DESCRIBING WORDS FOR PEOPLE, OBJECTS, THINGS, AND PLACES I. OBJECTIVE At the end of the 45-minute lesson, the students will be able to: 1. Use describing words to talk about people, objects, things, and places. (color, shape, size, height, weight, length, distance, etc.) 2. Match describing words to the attributes of what they are talking about. II. SUBJECT MATTER Topic: Recognizing and Using Describing Words (Attributes: Color, Shape, Size, Height, Weight, Length, Distance) References: Adapted from elementary oral language curricula and vocabulary development resources Materials: Visual aid (chart) titled "My Describing Word Toolkit" – with words and pictures: red, round, big, tall, heavy, long, far, cozy Props with different attributes: colored blocks, toys (ball, box, car, doll), books (thick, thin), plants (tall, short), photos of places (sunny park, quiet room) "Describe It!" cards (with pictures of people, objects, or places) Informal evaluation checklist III. PROCEDURE 1. PREPARATORY ACTIVITIES Warm-Up (5 minutes): Lead a "Word Clue" game: Say, "I’m thinking of something in this room that’s red. Can you guess what it is?" Have students call out guesses, then reveal the object. Repeat with 3-4 more clues (e.g., "It’s round," "It’s big"). 49 Motivation (5 minutes): Show a plain drawing of a cat and a colorful, detailed drawing of the same cat. Ask: "Which drawing tells you more about the cat? Why?" Explain: "Today, we’ll learn about ‘describing words’ – these are like magic clues that help us tell others exactly what something looks like, feels like, or where it is!" 2. DEVELOPMENTAL ACTIVITIES Introduce Describing Words: Display the "Describing Word Toolkit" chart. Point to each word and its picture, and say: "These words describe attributes – what something is like. ‘Red’ is a color, ‘round’ is