. Pairs switch roles after 5 minutes. Circulate to support: Remind students to use words from the toolkit and match them to the picture’s attributes. IV. EVALUATION Use an informal checklist to assess each student during the pair activity: Recognizes Uses describing Matches and names at words to talk about describing Criteria least 4 people/objects/places words to the describing correct words attributes Excellent Good Satisfactory Note: Assess by listening to each pair’s descriptions. Give positive feedback like, "Great use of ‘cozy’ for the bedroom!" or "Perfect – ‘tall’ matches the boy!" V. AGREEMENT For homework, students will: 1. Pick one thing at home (a toy, a pet, a room) and think of 3 describing words for it. 2. Tell a family member about it using those words (e.g., "My dog is brown, fluffy, and small"). Be ready to share their description with the class in our next lesson.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (212,4,NULL,'learn',14,'Additional intervention materials','reference','Use the original additional intervention material with your teacher. Your teacher will record which practice you completed.','29 Additional Intervention Material Learning Competency: Use describing words for people, objects, things and places (color, shape, size, height, weight, length, distance, etc.) Instructions: Show a red ball. Teacher says: Tell me something about the object I am holding. Rubrics 1 2 3 4 Pupil says “ball” Pupil says “a Pupil says “A Pupil says “It is ball” red ball” a red ball.” (or tell more something about it.) Additional Intervention Material Learning Competency: Talk about topics of interest Instruction: Tell me what you think about this picture. Additional Intervention Material Learning Competency: Asking Questions Instructions: Things you should know: • Number of Players: 2-10 • Setup: Choose 1 player to be “it,” and have them think of a secret person, place or thing. • Object of the game: Other players attempt to guess the secret person, place, or thing, but they only get 20 questions to do so.','assets/module/page-036.jpg','["assets/module/page-036.jpg"]','29 Additional Intervention Material Learning Competency: Use describing words for people, objects, things and places (color, shape, size, height, weight, length, distance, etc.) Instructions: Show a red ball. Teacher says: Tell me something about the object I am holding. Rubrics 1 2 3 4 Pupil says “ball” Pupil says “a Pupil says “A Pupil says “It is ball” red ball” a red ball.” (or tell more something about it.) Additional Intervention Material Learning Competency: Talk about topics of interest Instruction: Tell me what you think about this picture. Additional Intervention Material Learning Competency: Asking Questions Instructions: Things you should know: • Number of Players: 2-10 • Setup: Choose 1 player to be “it,” and have them think of a secret person, place or thing. • Object of the game: Other players attempt to guess the secret person, place, or thing, but they only get 20 questions to do so.',NULL,10,36,'29 Additional Intervention Material Learning Competency: Use describing words for people, objects, things and places (color, shape, size, height, weight, length, distance, etc.) Instructions: Show a red ball. Teacher says: Tell me something about the object I am holding. Rubrics 1 2 3 4 Pupil says “ball” Pupil says “a Pupil says “A Pupil says “It is ball” red ball” a red ball.” (or tell more something about it.) Additional Intervention Material Learning Competency: Talk about topics of interest Instruction: Tell me what you think about this picture. Additional Intervention Material Learning Competency: Asking Questions Instructions: Things you should know: • Number of Players: 2-10 • Setup: Choose 1 player to be “it,” and have them think of a secret person, place or thing. • Object of the game: Other players attempt to guess the secret person, place, or thing, but they only get 20 questions to do so.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (213,5,NULL,'learn',10,'Teacher-guided lesson checklist','reference','With your teacher, check all lesson procedures, evaluation, and home practice in the official guide. Your teacher confirms completion using the original checklist.','52 LESSON PLAN 5: ORAL LANGUAGE – TALKING ABOUT TOPICS OF INTEREST THROUGH PICTURE DISCUSSION I. OBJECTIVE At the end of the 45-minute lesson, the students will be able to: 1. Share their thoughts, feelings, and observations about a picture on a topic of interest; 2. Use simple sentence starters to organize their ideas clearly; 3. Listen respectfully to peers’ thoughts and ask one follow-up question. II. SUBJECT MATTER Topic: Talking About Topics of Interest (e.g., Toys, Pets, Parks, Festivals) "Tell Me What You Think About This Picture" References: Adapted from elementary oral communication curricula and expressive language development resources Materials: Visual aid (chart) with sentence starters: "I see…", "I think…", "I like…", "It makes me feel…" Colorful pictures of kid-friendly topics (e.g., a dog playing in a park, a birthday party with toys, a colorful festival, a cozy pet corner) "Picture Card Packs" (one pack per small group, with 3-4 pictures on different interests) informal evaluation checklist. 1. PREPARATORY ACTIVITIES Warm-Up Lead a "Quick Share" circle: Ask students to say one sentence about something they love (e.g., "I love my cat" or "I love playing with blocks"). Encourage them to speak clearly and look at the class. valuation checklist 53 Motivation Hold up a bright picture of a dog playing in a sunny park. Ask: "Who likes dogs? What do you see in this picture? What do you think the dog is feeling?" Let 2-3 students call out quick ideas, then say: "Today, we’ll learn to share our thoughts about pictures we like – and hear what our friends think too!" 2. DEVELOPMENTAL ACTIVITIES Introduce Picture Discussion: Display the visual aid with sentence starters. Explain: "When we talk about a picture, these sentences help us share what’s in our minds clearly. ‘I see’ tells what’s in the picture, ‘I think’ tells our ideas, and ‘I like’ tells what we enjoy about it." Model Sharing Thoughts: Focus on the dog park picture and share your own ideas: "I see a brown dog running with a red ball. I think the dog is happy because it’s playing in the sun. I like this picture because it makes me want to go to the park too!" Point to each sentence starter on the chart as you speak. Practice Sentence Starters: Have the class repeat the sentence starters together. Then, guide them to share one thought about the dog picture using one of the starters (e.g., "I see green grass" or "It makes me feel happy"). 3. ANALYSIS / DISCUSSION Ask: "What did I do to help you understand my thoughts about the picture?" (Let students point to the sentence starters.) Follow up: "Why is it fun to talk about pictures we like?" (e.g., "Because we can share what we love," "We can learn what our friends like too"). Remind them: "When others are talking, we listen carefully – that’s how we show we care about their ideas. We can even ask a small question, like ‘Why do you like that?’ to learn more!" 54 4. GUIDED PRACTICE "Picture Talk" Groups: Divide students into small groups (4-5 students each) and give each group a "Picture Card Pack" with topics they’ll enjoy. 1. One student picks a picture from the pack and shares their thoughts using at least 2 sentence starters. 2. The other students listen, then one peer asks a follow-up question (e.g., "What do you think the cat in the picture is eating?"). 3. Everyone in the group takes a turn picking a picture and sharing. Circulate around groups to support: Remind them to use the sentence starters, speak clearly, and listen respectfully. III. EVALUATION Use an informal checklist to assess each student during group discussion: Shares Uses at least 2 Listens thoughts/observations sentence respectfully to Criteria about the picture starters to peers and asks organize ideas a follow-up question Excellent Good Satisfactory Note: Assess by observing each student’s participation. Give positive feedback like, "Great use of ‘I think’!" or "Nice question – that helped us learn more!" IV. AGREEMENT For homework, students will: 1. - Find a picture at home (in a book, on a calendar, or on a device with family help) of something they love. 2. - Talk to a family member about it using the sentence starters: "I see…", "I think…", "I like…". Be ready to share their picture and thoughts with the class in our next lesson.','assets/module/page-060.jpg','["assets/module/page-060.jpg", "assets/module/page-061.jpg", "assets/module/page-062.jpg"]','52 LESSON PLAN 5: ORAL LANGUAGE – TALKING ABOUT TOPICS OF INTEREST THROUGH PICTURE DISCUSSION I. OBJECTIVE At the end of the 45-minute lesson, the students will be able to: 1. Share their thoughts, feelings, and observations about a picture on a topic of interest; 2. Use simple sentence starters to organize their ideas clearly; 3. Listen respectfully to peers’ thoughts and ask one follow-up question. II. SUBJECT MATTER Topic: Talking About Topics of Interest (e.g., Toys, Pets, Parks, Festivals) "Tell Me What You Think About This Picture" References: Adapted from elementary oral communication curricula and expressive language development resources Materials: Visual aid (chart) with sentence starters: "I see…", "I think…", "I like…", "It makes me feel…" Colorful pictures of kid-friendly topics (e.g., a dog playing in a park, a birthday party with toys, a colorful festival, a cozy pet corner) "Picture Card Packs" (one pack per small group, with 3-4 pictures on different interests) informal evaluation checklist. 1. PREPARATORY ACTIVITIES Warm-Up Lead a "Quick Share" circle: Ask students to say one sentence about something they love (e.g.,