r thoughts using at least 2 sentence starters. 2. The other students listen, then one peer asks a follow-up question (e.g., "What do you think the cat in the picture is eating?"). 3. Everyone in the group takes a turn picking a picture and sharing. Circulate around groups to support: Remind them to use the sentence starters, speak clearly, and listen respectfully. III. EVALUATION Use an informal checklist to assess each student during group discussion: Shares Uses at least 2 Listens thoughts/observations sentence respectfully to Criteria about the picture starters to peers and asks organize ideas a follow-up question Excellent Good Satisfactory Note: Assess by observing each student’s participation. Give positive feedback like, "Great use of ‘I think’!" or "Nice question – that helped us learn more!" IV. AGREEMENT For homework, students will: 1. - Find a picture at home (in a book, on a calendar, or on a device with family help) of something they love. 2. - Talk to a family member about it using the sentence starters: "I see…", "I think…", "I like…". Be ready to share their picture and thoughts with the class in our next lesson.',NULL,10,60,'52 LESSON PLAN 5: ORAL LANGUAGE – TALKING ABOUT TOPICS OF INTEREST THROUGH PICTURE DISCUSSION I. OBJECTIVE At the end of the 45-minute lesson, the students will be able to: 1. Share their thoughts, feelings, and observations about a picture on a topic of interest; 2. Use simple sentence starters to organize their ideas clearly; 3. Listen respectfully to peers’ thoughts and ask one follow-up question. II. SUBJECT MATTER Topic: Talking About Topics of Interest (e.g., Toys, Pets, Parks, Festivals) "Tell Me What You Think About This Picture" References: Adapted from elementary oral communication curricula and expressive language development resources Materials: Visual aid (chart) with sentence starters: "I see…", "I think…", "I like…", "It makes me feel…" Colorful pictures of kid-friendly topics (e.g., a dog playing in a park, a bir