eas. We can even ask a small question, like ‘Why do you like that?’ to learn more!" 54 4. GUIDED PRACTICE "Picture Talk" Groups: Divide students into small groups (4-5 students each) and give each group a "Picture Card Pack" with topics they’ll enjoy. 1. One student picks a picture from the pack and shares their thoughts using at least 2 sentence starters. 2. The other students listen, then one peer asks a follow-up question (e.g., "What do you think the cat in the picture is eating?"). 3. Everyone in the group takes a turn picking a picture and sharing. Circulate around groups to support: Remind them to use the sentence starters, speak clearly, and listen respectfully. III. EVALUATION Use an informal checklist to assess each student during group discussion: Shares Uses at least 2 Listens thoughts/observations sentence respectfully to Criteria about the picture starters to peers and asks organize ideas a follow-up question Excellent Good Satisfactory Note: Assess by observing each student’s participation. Give positive feedback like, "Great use of ‘I think’!" or "Nice question – that helped us learn more!" IV. AGREEMENT For homework, students will: 1. - Find a picture at home (in a book, on a calendar, or on a device with family help) of something they love. 2. - Talk to a family member about it using the sentence starters: "I see…", "I think…", "I like…". Be ready to share their picture and thoughts with the class in our next lesson.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (214,5,NULL,'learn',11,'Additional intervention materials','reference','Use the original additional intervention material with your teacher. Your teacher will record which practice you completed.','29 Additional Intervention Material Learning Competency: Use describing words for people, objects, things and places (color, shape, size, height, weight, length, distance, etc.) Instructions: Show a red ball. Teacher says: Tell me something about the object I am holding. Rubrics 1 2 3 4 Pupil says “ball” Pupil says “a Pupil says “A Pupil says “It is ball” red ball” a red ball.” (or tell more something about it.) Additional Intervention Material Learning Competency: Talk about topics of interest Instruction: Tell me what you think about this picture. Additional Intervention Material Learning Competency: Asking Questions Instructions: Things you should know: • Number of Players: 2-10 • Setup: Choose 1 player to be “it,” and have them think of a secret person, place or thing. • Object of the game: Other players attempt to guess the secret person, place, or thing, but they only get 20 questions to do so.

30 "This game works best with a small to medium-sized group of people, so that everyone gets a chance to ask a question. Choose a random player to be “it.” This could be the youngest player in the group, the player who’s had the most recent birthday, or something silly, like who can eat a piece of pizza the fastest. Question 1 Think of a person, place, or thing for other players to guess if you’re “it. ”Think of someone or something that you know enough about to answer some basic questions about, and keep it a secret! If you choose a person, they can be living, deceased, or even fictional. Make sure you choose a person, place, or thing that most people in your group know about. • For example, your item could be “Manny Pacquiao,” since he is famous enough that most people will be able to make guesses about him. You could also choose something like your town, Philippines, or even clouds or the sun. • Avoid items like “my mom” or “my dog” unless you are with your siblings or best friends, since the players might not know enough about them to guess. Question 2 Ask yes-or-no questions if you''re not "it. "If you’re not “it,” your goal is to figure out what the “it” person is thinking of by asking questions to narrow down the possibilities. Try using a fairly general opening question that can be answered with “yes” or “no” to narrow down your options.

31 For example: • “Is it alive?” • “Is it an object?” • “Is it fictional?” • “Is it bigger than a toaster? Question 3 Take turns asking more specific yes-or-no questions to narrow it down. You can ask questions in any order that you’d like, but make sure each player gets to ask at least 1 question. If a player asks a question that can’t be answered with “yes” or “no,” ask them to rephrase it so that it can be, since the person who’s “it” can only say “yes” or “no.” • For example, a player couldn’t ask, “How old are they?” or “What do they look like?” They could ask, “Are they older than 50?” or, “Do they have blonde hair?” Think about the questions that have already been asked before you ask new questions. For example, you could go from "Is it a person?" to "Is it a man?" to "Are they alive?" to "Do they live in the Philippines?" Play until you reach 10 questions or someone guesses the right answer. Become the next “it” person if you guess the correct answer. The person who guesses the right answer is next to be “it,” and they think up their own secret person, place, or thing. If no one guessed the person, place, or thing at all, whoever wants to go next can have a turn. Keep the game going until everyone has had a chance to be “it.” • If someone guesses correctly but they’ve already been “it,” let someone else have a turn instead. Giving everyone a turn makes the game more inclusive and lets everybody have some fun!','assets/module/page-036.jpg','["assets/module/page-036.jpg", "assets/module/page-037.jpg", "assets/module/page-038.jpg"]','29 Additional Intervention Material Learning Competency: Use describing words for people, objects, things and places (color, shape, size, height, weight, length, distance, etc.) Instructions: Show a red ball. Teacher says: Tell me something about the object I am holding. Rubrics 1 2 3 4 Pupil says “ball” Pupil says “a Pupil says “A Pupil says “It is ball” red ball” a red ball.” (or tell more something about it.) Additional Intervention Material Learning Competency: Talk about topics of interest Instruction: Tell me what you think about this picture. Additional Intervention Material Learning Competency: Asking Questions Instructions: Things you should know: • Number of Players: 2-10 • Setup: Choose 1 player to be “it,” and have them think of a secret person, place or thing. • Object of the game: Other players attempt to guess the secret person, place, or thing, but they only get 20 questions to do so.

30 "This game works best with a small to medium-sized group of people, so that everyone gets a chance to ask a question. Choose a random player to be “it.” This could be the youngest player in the group, the player who’s had the most recent birthday, or something silly, like who can eat a piece of pizza the fastest. Question 1 Think of a person, place, or thing for other players to guess if you’re “it. ”Think of someone or something that you know enough about to answer some basic questions about, and keep it a secret! If you choose a person, they can be living, deceased, or even fictional. Make sure you choose a person, place, or thing that most people in your group know about. • For example, your item could be “Manny Pacquiao,” since he is famous enough that most people will be able to make guesses about him. You could also choose something like your town, Philippines, or even clouds or the sun. • Avoid items like “my mom” or “my dog” unless you are with your siblings or best friends, since the players might not know enough about them to guess. Question 2 Ask yes-or-no questions if you''re not "it. "If you’re not “it,” your goal is to figure out what the “it” person is thinking of by asking questions to narrow down the possibilities. Try using a fairly general opening question that can be answered with “yes” or “no” to narrow down your options.

31 For example: • “Is it alive?” • “Is it an object?” • “Is it fictional?” • “Is it bigger than a toaster? Question 3 Take turns asking more specific yes-or-no questions to narrow it down. You can ask questions in any order that you’d like, but make sure each player gets to ask at least 1 question. If a player asks a question that can’t be answered with “yes” or “no,” ask them to rephrase it so that it can be, since the person who’s “it” can only say “yes” or “no.” • For example, a player couldn’t ask, “How old are they?” or “What do they look like?” They could ask, “Are they older than 50?” or, “Do they have blonde hair?” Think about the questions that have already been asked before you ask new questions. For example, you could go from "Is it a person?" to "Is it a man?" to "Are they alive?" to "Do they live in the Philippines?" Play until you reach 10 questions or someone guesses the right answer. Become the next “it” person if you guess the correct answer. The person who guesses the right answer is next to be “it,” and they think up their own secret person, place, or thing. If no one guessed the person, place, or thing at all, whoever wants to go next can have a turn. Keep the game going until everyone has had a chance to be “it.” • If someone guesses correctly but they’ve already been “it,” let someone else have a turn instead. Giving everyone a turn makes the game more inclusive and lets everybody have some fun!',NULL,10,36,'29 Additional Intervention Material Learning Competency: Use describing words for people, objects, things and places (color, shape, size, height, weight, length, distance, etc.) Instructions: Show a red ball. Teacher says: Tell me something about the object I am holding. Rubrics 1 2 3 4 Pupil says “ball” Pupil says “a Pupil says “A Pupil says “It is ball” red ball” a red ball.” (or tell more something about it.) Additional Intervention Material Learning Competency: Talk about topics of interest Instruction: Tell me what you think about this picture. Additional Intervention Material Learning Competency: Asking Questions Instructions: Things you should know: • Number of Players: 2-10 • Setup: Choose 1 player to be “it,” and have them think of a secret person, place or thing. • Object of the game: Other players attempt to guess the secret person, place, or thing, but they only get 20 questions to do so.

30 "This game works best with a small to medium-sized group of people, so that everyone gets a chance to ask a question. Choose a random player to be “it.” This could be the youngest player in the group, the player who’s had the most recent birthday, or something silly, like who can eat a piece of pizza the fastest. Question 1 Think of a person, place, or thing for other players to guess if you’re “it. ”Think of someone or something that you know enough about to answer some basic questions about, and keep it a secret! If you choose a person, they can be living, deceased, or even fictional. Make sure you choose a person, place, or thing that most people in your group know about. • For example, your item could be “Manny Pacquiao,” since he is famous enough that most people will be able to make guesses about him. You could also choose something like your town, Philippines, or even clouds or the sun. • Avoid items like “my mom” or “my dog” unless you are with your siblings or best friends, since the players might not know enough about them to guess. Question 2 Ask yes-or-no questions if you''re not "it. "If you’re not “it,” your goal is to figure out what the “it” person is thinking of by asking questions to narrow down the possibilities. Try using a fairly general opening question that can be answered with “yes” or “no” to narrow down your options.

31 For example: • “Is it alive?” • “Is it an object?” • “Is it fictional?” • “Is it bigger than a toaster? Question 3 Take turns asking more specific yes-or-no questions to narrow it down. You can ask questions in any order that you’d like, but make sure each player gets to ask at least 1 question. If a player asks a question that can’t be answered with “yes” or “no,” ask them to rephrase it so that it can be, since the person who’s “it” can only say “yes” or “no.” • For example, a player couldn’t ask, “How old are they?” or “What do they look like?” They could ask, “Are they older than 50?” or, “Do they have blonde hair?” Think about the questions that have already been asked before you ask new questions. For example, you could go from "Is it a person?" to "Is it a man?" to "Are they alive?" to "Do they live in the Philippines?" Play until you reach 10 questions or someone guesses the right answer. Become the next “it” person if you guess the correct answer. The person who guesses the right answer is next to be “it,” and they think up their own secret person, place, or thing. If no one guessed the person, place, or thing at all, whoever wants to go next can have a turn. Keep the game going until everyone has had a chance to be “it.” • If someone guesses correctly but they’ve already been “it,” let someone else have a turn instead. Giving everyone a turn makes the game more inclusive and lets everybody have some fun!');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (215,6,NULL,'learn',7,'Teacher-guided lesson checklist','reference','With your teacher, check all lesson procedures, evaluation, and home practice in the official guide. Your teacher confirms completion using the original checklist.','55 LESSON PLAN 6: ORAL LANGUAGE – DESCRIBE AND DRAW I. OBJECTIVE At the end of the 45-minute lesson, the students will be able to: 1. Use specific describing words (color, shape, size, position) to clearly describe a picture; 2. Listen carefully to a peer’s description and draw what they hear; 3. Identify 2-3 key details that make a description easy to understand. II. SUBJECT MATTER Topic: "Describe and Draw" – Using Oral Language to Share Visual Details References: Adapted from elementary oral communication curricula and expressive/receptive language development resources Materials: Teacher’s model picture (colorful, with clear details: e.g., a red bird on a green tree branch next to a yellow flower) Set of "secret pictures" (one per pair, different from each other, with simple, distinct elements) Paper and crayons for each student Visual aid (chart) with key describing words: color words, round, square, big, small, on top, next to, under Informal evaluation checklist III. PROCEDURE 1. PREPARATORY ACTIVITIES Warm-Up Lead a "Quick Draw" game: Say, "I’m going to describe something—draw what you hear!" Describe a simple object (e.g., "a small, blue square") and have students draw it. Show their drawings and talk about how clear words helped them. Motivation Hold up your model picture (but don’t show it to the class yet). Say: "I have a secret picture! If I describe it well enough, you’ll be able to draw it without even seeing it. Want to try? Today, we’ll play a ‘Describe and Draw’ game where we’re like ‘picture messengers’—using words to send images to our friends!" 56 2. DEVELOPMENTAL ACTIVITIES Introduce Key Description Details: Display the visual aid. Explain: "When we describe a picture, we need to share details like what color things are, what shape they are, how big they are, and where they are. These details help the person drawing know exactly what to put on their paper." Teacher Modeling: Show the model picture to the class for 10 seconds, then hide it. Describe it slowly and clearly: "First, there’s a big, green tree branch in the middle. On top of the branch, there’s a small, red bird with a yellow beak. Next to the bird, there’s a bright yellow flower with five petals. The sky behind is light blue." As you describe, point to the words on the visual aid. Have students draw along as you speak. Check and Discuss: Show the model picture again and let students compare their drawings. Ask: "What details helped you draw it right?" (e.g., "‘on top’ told me where the bird was," "‘red’ told me its color"). 3. ANALYSIS / DISCUSSION Ask: "What would happen if I forgot to say ‘small’ about the bird? Or ‘next to the bird’ about the flower?" (Let students share: "I might draw a big bird," "I might put the flower somewhere else"). Follow up: "Why is it important to describe things in order (e.g., ‘first the branch, then the bird’)?" (e.g., "So the drawer knows what to draw first," "It’s easier to follow"). Remind students: "As a describer, your job is to be clear. As a drawer, your job is to listen closely—no peeking at the picture!" 4. GUIDED PRACTICE Pair "Describe and Draw" Activity: Divide students into pairs. Give one student in each pair a "secret picture" (they must not show it 57 to their partner). Assign roles: Describer (has the picture) and Drawer (listens and draws). 1. The Describer looks at their picture and describes it using key details and the visual aid words. 2. The Drawer listens carefully and draws what they hear—they can ask clarifying questions (e.g., "Is the cat big or small?"). 3. After 5 minutes, have pairs switch roles with a new secret picture. Circulate around pairs to support: Remind Describers to use specific details and Drawers to listen actively. IV. EVALUATION Use an informal checklist to assess each student in both roles Uses specific Captures key Listens Criteria describing words details from the respectfully and (color, shape, description asks clarifying position) As Drawer questions (when As Describer drawing) Excellent Good Satisfactory Note: Assess by observing pairs and looking at their drawings. Give positive feedback like, "Great job saying ‘under the tree’—that helped your partner draw it right!" V. AGREEMENT For homework, students will: 1. Pick a favorite toy at home (e.g., a doll, car, teddy bear). 2. Describe the toy in detail to a family member, who will draw it based on their description. 3. Bring both the toy and the family’s drawing to share with the class in our next lesson.','assets/module/page-063.jpg','["assets/module/page-063.jpg", "assets/module/page-064.jpg", "assets/module/page-065.jpg"]','55 LESSON PLAN 6: ORAL LANGUAGE – DESCRIBE AND DRAW I. OBJECTIVE At the end of the 45-minute lesson, the students will be able to: 1. Use specific describing words (color, shape, size, position) to clearly describe a picture; 2. Listen carefully to a peer’s description and draw what they hear; 3. Identify 2-3 key details that make a description easy to understand. II. SUBJECT MATTER Topic: "Describe and Draw" – Using Oral Language to Share Visual Details References: Adapted from elementary oral communication curricula and expressive/receptive language development resources Materials: Teacher’s model picture (colorful, with clear details: e.g., a red bird on a green tree branch next to a yellow flower) Set of "secret pictures" (one per pair, different from each other, with simple, distinct elements) Paper and crayons for each student Visual aid (chart) with key describing words: color words, round, square, big, small, on top, next to, under Informal evaluation checklist III. PROCEDURE 1. PREPARATORY ACTIVITIES Warm-Up Lead a "Quick Draw" game: Say, "I’m going to describe something—draw what you hear!" Describe a simple object (e.g., "a small, blue square") and have students draw it. Show their drawings and talk about how clear words helped them. Motivation Hold up your model picture (but don’t show it to the class yet). Say: "I have a secret picture! If I describe it well enough, you’ll be able to draw it without even seeing it. Want to try? Today, we’ll play a ‘Describe and Draw’ game where we’re like ‘picture messengers’—using words to send images to our friends!" 56 2. DEVELOPMENTAL ACTIVITIES Introduce Key Description Details: Display the visual aid. Explain: "When we describe a picture, we need to share details like what color things are, what shape they are, how big they are, and where they are. These details help the person drawing know exactly what to put on their paper." Teacher Modeling: Show the model picture to the class for 10 seconds, then hide it. Describe it slowly and clearly: "First, there’s a big, green tree branch in the middle. On top of the branch, there’s a small, red bird with a yellow beak. Next to the bird, there’s a bright yellow flower with five petals. The sky behind is light blue." As you describe, point to the words on the visual aid. Have students draw along as you speak. Check and Discuss: Show the model picture again and let students compare their drawings. Ask: "What details helped you draw it right?" (e.g., "‘on top’ told me where the bird was," "‘red’ told me its color"). 3. ANALYSIS / DISCUSSION Ask: "What would happen if I forgot to say ‘small’ about the bird? Or ‘next to the bird’ about the flower?" (Let students share: "I might draw a big bird," "I might put the flower somewhere else"). Follow up: "Why is it important to describe things in order (e.g., ‘first the branch, then the bird’)?" (e.g., "So the drawer knows what to draw first," "It’s easier to follow"). Remind students: "As a describer, your job is to be clear. As a drawer, your job is to listen closely—no peeking at the picture!" 4. GUIDED PRACTICE Pair "Describe and Draw" Activity: Divide students into pairs. Give one student in each pair a "secret picture" (they must not show it 57 to their partner). Assign roles: Describer (has the picture) and Drawer (listens and draws). 1. The Describer looks at their picture and describes it using key details and the visual aid words. 2. The Drawer listens carefully and draws what they hear—they can ask clarifying questions (e.g., "Is the cat big or small?"). 3. After 5 minutes, have pairs switch roles with a new secret picture. Circulate around pairs to support: Remind Describers to use specific details and Drawers to listen actively. IV. EVALUATION Use an informal checklist to assess each student in both roles Uses specific Captures key Listens Criteria describing words details from the respectfully and (color, shape, description asks clarifying position) As Drawer questions (when As Describer drawing) Excellent Good Satisfactory Note: Assess by observing pairs and looking at their drawings. Give positive feedback like, "Great job saying ‘under the tree’—that helped your partner draw it right!" V. AGREEMENT For homework, students will: 1. Pick a favorite toy at home (e.g., a doll, car, teddy bear). 2. Describe the toy in detail to a family member, who will draw it based on their description. 3. Bring both the toy and the family’s drawing to share with the class in our next lesson.',NULL,10,63,'55 LESSON PLAN 6: ORAL LANGUAGE – DESCRIBE AND DRAW I. OBJECTIVE At the end of the 45-minute lesson, the students will be able to: 1. Use specific describing words (color, shape, size, position) to clearly describe a picture; 2. Listen carefully to a peer’s description and draw what they hear; 3. Identify 2-3 key details that make a description easy to understand. II. SUBJECT MATTER Topic: "Describe and Draw" – Using Oral Lan