gs. Ask: "What details helped you draw it right?" (e.g., "‘on top’ told me where the bird was," "‘red’ told me its color"). 3. ANALYSIS / DISCUSSION Ask: "What would happen if I forgot to say ‘small’ about the bird? Or ‘next to the bird’ about the flower?" (Let students share: "I might draw a big bird," "I might put the flower somewhere else"). Follow up: "Why is it important to describe things in order (e.g., ‘first the branch, then the bird’)?" (e.g., "So the drawer knows what to draw first," "It’s easier to follow"). Remind students: "As a describer, your job is to be clear. As a drawer, your job is to listen closely—no peeking at the picture!" 4. GUIDED PRACTICE Pair "Describe and Draw" Activity: Divide students into pairs. Give one student in each pair a "secret picture" (they must not show it 57 to their partner). Assign roles: Describer (has the picture) and Drawer (listens and draws). 1. The Describer looks at their picture and describes it using key details and the visual aid words. 2. The Drawer listens carefully and draws what they hear—they can ask clarifying questions (e.g., "Is the cat big or small?"). 3. After 5 minutes, have pairs switch roles with a new secret picture. Circulate around pairs to support: Remind Describers to use specific details and Drawers to listen actively. IV. EVALUATION Use an informal checklist to assess each student in both roles Uses specific Captures key Listens Criteria describing words details from the respectfully and (color, shape, description asks clarifying position) As Drawer questions (when As Describer drawing) Excellent Good Satisfactory Note: Assess by observing pairs and looking at their drawings. Give positive feedback like, "Great job saying ‘under the tree’—that helped your partner draw it right!" V. AGREEMENT For homework, students will: 1. Pick a favorite toy at home (e.g., a doll, car, teddy bear). 2. Describe the toy in detail to a family member, who will draw it based on their description. 3. Bring both the toy and the family’s drawing to share with the class in our next lesson.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (216,6,NULL,'learn',8,'Additional intervention materials','reference','Use the original additional intervention material with your teacher. Your teacher will record which practice you completed.','32 Additional Intervention Material DESCRIBE and DRAW Instructions: 1. Show a picture. The picture might be a page from a storybook that the children are familiar with, or a picture like one of these. 2. Ask children what they see. “What do you see in the pictures?” or “What do you notice?” Learners’ answers may vary. Accept their responses. We want to get children to begin to describe what they see in their own words. • “I see a house.” • “I see a door.” • “I see a girl flying.” • “I see a weird tree.” • “I see squares.” 3. Take the children''s lead and respond to their ideas by asking follow-up questions. • "Where do you see the squares? Where do you see the tree?" • "Can you tell me more about the ?" • "What do you notice about what’s in the back corner?" • "How do you know that this is a triangle? Are those both triangles?" 4. Ask students to draw what they see. • Keep the picture available; this is not a memory task. • This is not a tracing task either. We are asking children to draw what they see. (Expect a wide variety!) • Children often begin by drawing portions of the picture (just the tree, just the oval for the body of the tree, etc.)

33 5. Move around and check in with them as they are drawing. You can ask questions based on what they drew to get them to add detail to their drawing. It is important to remember that the children should not think that the drawing has to look exactly like the picture. “You draw what YOU see.” (You might want to remind children that what they see might be different from what someone else sees.) 6. As children finish, ask them to tell you about what they drew. Older children could describe their own drawing to a partner, and vice versa. After discussion, children should go back and add detail to their own drawing. 7. Consider sharing a couple of examples of children''s drawings and ask the child to describe to the class what they drew. Let other children add what they see. Use this as an opportunity to highlight one idea you want to engage the group in (perhaps noticing a particular shape, or using specific language such as above or below, or describing where an object is in relation to other objects).

34','assets/module/page-039.jpg','["assets/module/page-039.jpg", "assets/module/page-040.jpg", "assets/module/page-041.jpg"]','32 Additional Intervention Material DESCRIBE and DRAW Instructions: 1. Show a picture. The picture might be a page from a storybook that the children are familiar with, or a picture like one of these. 2. Ask children what they see. “What do you see in the pictures?” or “What do you notice?” Learners’ answers may vary. Accept their responses. We want to get children to begin to describe what they see in their own words. • “I see a house.” • “I see a door.” • “I see a girl flying.” • “I see a weird tree.” • “I see squares.” 3. Take the children''s lead and respond to their ideas by asking follow-up questions. • "Where do you see the squares? Where do you see the tree?" • "Can you tell me more about the ?" • "What do you notice about what’s in the back corner?" • "How do you know that this is a triangle? Are those both triangles?" 4. Ask students to draw what they see. • Keep the picture available; this is not a memory task. • This is not a tracing task either. We are asking children to draw what they see. (Expect a wide variety!) • Children often begin by drawing portions of the picture (just the tree, just the oval for the body of the tree, etc.)

33 5. Move around and check in with them as they are drawing. You can ask questions based on what they drew to get them to add detail to their drawing. It is important to remember that the children should not think that the drawing has to look exactly like the picture. “You draw what YOU see.” (You might want to remind children that what they see might be different from what someone else sees.) 6. As children finish, ask them to tell you about what they drew. Older children could describe their own drawing to a partner, and vice versa. After discussion, children should go back and add detail to their own drawing. 7. Consider sharing a couple of examples of children''s drawings and ask the child to describe to the class what they drew. Let other children add what they see. Use this as an opportunity to highlight one idea you want to engage the group in (perhaps noticing a particular shape, or using specific language such as above or below, or describing where an object is in relation to other objects).

34',NULL,10,39,'32 Additional Intervention Material DESCRIBE and DRAW Instructions: 1. Show a picture. The picture might be a page from a storybook that the children are familiar with, or a picture like one of these. 2. Ask children what they see. “What do you see in the pictures?” or “What do you notice?” Learners’ answers may vary. Accept their responses. We want to get children to begin to describe what they see in their own words. • “I see a house.” • “I see a door.” • “I see a girl flying.” • “I see a weird tree.” • “I see squares.” 3. Take the children''s lead and respond to their ideas by asking follow-up questions. • "Where do you see the squares? Where do you see the tree?" • "Can you tell me more about the ?" • "What do you notice about what’s in the back corner?" • "How do you know that this is a triangle? Are those both triangles?" 4. Ask students to draw what they see. • Keep the picture available; this is not a memory task. • This is not a tracing task either. We are asking children to draw what they see. (Expect a wide variety!) • Children often begin by drawing portions of the picture (just the tree, just the oval for the body of the tree, etc.)

33 5. Move around and check in with them as they are drawing. You can ask questions based on what they drew to get them to add detail to their drawing. It is important to remember that the children should not think that the drawing has to look exactly like the picture. “You draw what YOU see.” (You might want to remind children that what they see might be different from what someone else sees.) 6. As children finish, ask them to tell you about what they drew. Older children could describe their own drawing to a partner, and vice versa. After discussion, children should go back and add detail to their own drawing. 7. Consider sharing a couple of examples of children''s drawings and ask the child to describe to the class what they drew. Let other children add what they see. Use this as an opportunity to highlight one idea you want to engage the group in (perhaps noticing a particular shape, or using specific language such as above or below, or describing where an object is in relation to other objects).

34');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (217,7,NULL,'learn',7,'Teacher-guided lesson checklist','reference','With your teacher, check all lesson procedures, evaluation, and home practice in the official guide. Your teacher confirms completion using the original checklist.','58 LESSON PLAN 7: ORAL LANGUAGE USING PICTURE STORY CHAIN STRATEGY I. OBJECTIVES By the end of the lesson, students will be able to: 1. Identify key elements (characters, setting, action) in a sequence of pictures. 2. Contribute at least one sentence to a group "picture story chain." 3. Speak clearly and listen attentively when participating in the group activity. II. SUBJECT MATTER Topic: Oral Language Development through Picture Story Chain Strategy: Picture Story Chain (collaborative storytelling using a sequence of images) Materials: 5-6 colorful, simple picture cards (no text) showing a logical sequence (e.g., a cat waking up → going outside → finding a ball → playing with it → going home → sleeping again) Whiteboard or chart paper Marker Sticky notes for student contributions Skills: Speaking, listening, sequencing, critical thinking Values Integration: Cooperation, respect for others’ ideas III. LEARNING PROCEDURE A. MOTIVATION "Guess the Next Picture" Game: Show the first 2 picture cards one by one. Ask: "What do you see in this picture? What do you think will happen next?" Let 2-3 students share their guesses to activate prior knowledge and spark curiosity. 59 B. LESSON PROPER 1. INTRODUCTION TO PICTURE STORY CHAIN Show all 4-5 picture cards in order on the board. Explain: “Today, we’ll make a story together using these pictures! This is called a ''Picture Story Chain.'' Each of you will add one sentence to the story, just like linking chains together." Point to each picture and ask students to name what they see (e.g., "This is a cat. This is a garden. This is a ball.") to build vocabulary. 2. MODELING THE ACTIVITY Start the story with the first picture: "Once upon a time, there was a little cat named Mimi. She woke up early in her cozy bed." Move to the second picture and add: "Mimi jumped out of bed and walked outside to the garden. Write these sentences on the chart paper to show how the story builds. Emphasize: "Each sentence should connect to the picture and the one before it!" 60 3. GROUP PICTURE STORY CHAIN Divide the class into 5 small groups (4-5 students each). Group 1 Group 2 61 Group 3 Group 4 62 Group 5 Give each group a set of the picture cards arranged in order. Instructions for groups: • The first student looks at the first picture and says one sentence. • The next student looks at the second picture and says a sentence that connects to the first. • Continue until all pictures are used and the story has an ending. • One student from each group will share the complete story with the class. Roam around groups to support: Encourage shy students to participate (e.g., "Can you say, ''Mimi found a red ball''?") Help students connect their sentences (e.g., "Great! After Mimi plays with the ball, what happens next?") Write key sentences on sticky notes for each group to display. C. GENERALIZATION Gather the class and have both groups share their stories. Ask: "How did working together help us make the story?" (Expected answer: "We shared ideas, listened to each other, and made a long story together.") Conclude: "Pictures can help us tell stories, and when we work in a chain, we can make amazing stories with our friends!" 63 IV. EVALUATION Formative Assessment: Observe students during the group activity and check if they: Contribute at least one sentence. Speak clearly. Listen to others. Use a simple checklist to record participation and understanding. V. ASSIGNMENT At home, ask students to find 3 simple pictures (from a book or magazine) and make a short story with their family using the picture story chain strategy. They will share their story with the class in the next lesson. VI. REFLECTION (For teacher’s use only: Note which students struggled with speaking/listening, which pictures were most effective, and adjustments for future lessons.) Picture Card Suggestion (Description for Visuals): 1. A small cat lying in a bed with eyes closed. 2. The cat standing by an open door, looking outside. 3. The cat in a garden with green grass and flowers. 4. The cat playing with a red ball. 5. The cat walking back towards the house with the ball. 6. The cat back in bed, sleeping with the ball beside it.','assets/module/page-066.jpg','["assets/module/page-066.jpg", "assets/module/page-067.jpg", "assets/module/page-068.jpg", "assets/module/page-069.jpg", "assets/module/page-070.jpg", "assets/module/page-071.jpg"]','58 LESSON PLAN 7: ORAL LANGUAGE USING PICTURE STORY CHAIN STRATEGY I. OBJECTIVES By the end of the lesson, students will be able to: 1. Identify key elements (characters, setting, action) in a sequence of pictures. 2. Contribute at least one sentence to a group "picture story chain." 3. Speak clearly and listen attentively when participating in the group activity. II. SUBJECT MATTER Topic: Oral Language Development through Picture Story Chain Strategy: Picture Story Chain (collaborative storytelling using a sequence of images) Materials: 5-6 colorful, simple picture cards (no text) showing a logical sequence (e.g., a cat waking up → going outside → finding a ball → playing with it → going home → sleeping again) Whiteboard or chart paper Marker Sticky notes for student contributions Skills: Speaking, listening, sequencing, critical thinking Values Integration: Cooperation, respect for others’ ideas III. LEARNING PROCEDURE A. MOTIVATION "Guess the Next Picture" Game: Show the first 2 picture cards one by one. Ask: "What do you see in this picture? What do you think will happen next?" Let 2-3 students share their guesses to activate prior knowledge and spark curiosity. 59 B. LESSON PROPER 1. INTRODUCTION TO PICTURE STORY CHAIN Show all 4-5 picture cards in order on the board. Explain: “Today, we’ll make a story together using these pictures! This is called a ''Picture Story Chain.'' Each of you will add one sentence to the story, just like linking chains together." Point to each picture and ask students to name what they see (e.g., "This is a cat. This is a garden. This is a ball.") to build vocabulary. 2. MODELING THE ACTIVITY Start the story with the first picture: "Once upon a time, there was a little cat named Mimi. She woke up early in her cozy bed." Move to the second picture and add: "Mimi jumped out of bed and walked outside to the garden. Write these sentences on the chart paper to show how the story builds. Emphasize: "Each sentence should connect to the picture and the one before it!" 60 3. GROUP PICTURE STORY CHAIN Divide the class into 5 small groups (4-5 students each). Group 1 Group 2 61 Group 3 Group 4 62 Group 5 Give each group a set of the picture cards arranged in order. Instructions for groups: • The first student looks at the first picture and says one sentence. • The next student looks at the second picture and says a sentence that connects to the first. • Continue until all pictures are used and the story has an ending. • One student from each group will share the complete story with the class. Roam around groups to support: Encourage shy students to participate (e.g., "Can you say, ''Mimi found a red ball''?") Help students connect their sentences (e.g., "Great! After Mimi plays with the ball, what happens next?") Write key sentences on sticky notes for each group to display. C. GENERALIZATION Gather the class and have both groups share their stories. Ask: "How did working together help us make the story?" (Expected answer: "We shared ideas, listened to each other, and made a long story together.") Conclude: "Pictures can help us tell stories, and when we work in a chain, we can make amazing stories with our friends!" 63 IV. EVALUATION Formative Assessment: Observe students during the group activity and check if they: Contribute at least one sentence. Speak clearly. Listen to others. Use a simple checklist to record participation and understanding. V. ASSIGNMENT At home, ask students to find 3 simple pictures (from a book or magazine) and make a short story with their family using the picture story chain strategy. They will share their story with the class in the next lesson. VI. REFLECTION (For teacher’s use only: Note which students struggled with speaking/listening, which pictures were most effective, and adjustments for future lessons.) Picture Card Suggestion (Description for Visuals): 1. A small cat lying in a bed with eyes closed. 2. The cat standing by an open door, looking outside. 3. The cat in a garden with green grass and flowers. 4. The cat playing with a red ball. 5. The cat walking back towards the house with the ball. 6. The cat back in bed, sleeping with the ball beside it.',NULL,10,66,'58 LESSON PLAN 7: ORAL LANGUAGE USING PICTURE STORY CHAIN STRATEGY I. OBJECTIVES By the end of the lesson, students will be able to: 1. Identify key elements (characters, setting, action) in a sequence of pictures. 2. Contribute at least one sentence to a group "picture story chain." 3. Speak clearly and listen attentively when participating in the group activity. II. SUBJECT MATTER Topic: Oral Language Development through Picture Story Chain Strategy: Picture Story Chain (collaborative storytelling using a sequence of images) Materials: 5-6 colorful, simple picture cards (no text) showing a logical sequence (e.g., a cat waking up → going outside → finding a ball → playing with it → going home → sleeping again) Whiteboard or chart paper Marker Sticky notes for student contributions Skills: Speaking, listening, sequencing, critical thinking Values Integration: Cooperation, respect for others’ ideas III. LEARNING PROCEDURE A. MOTIVATION "Guess the Next Picture" Game: Show the first 2 picture cards one by one. Ask: "What do you see in this picture? What do you think will happen next?" Let 2-3 students share their guesses to activate prior knowledge and spark curiosity. 59 B. LESSON PROPER 1. INTRODUCTION TO PICTURE STORY CHAIN Show all 4-5 picture cards in order on the board. Explain: “Today, we’ll make a story together using these pictures! This is called a ''Picture Story Chain.'' Each of you will add one sentence to the story, just like linking chains together." Point to each picture and ask students to name what they see (e.g., "This is a cat. This is a garden. This is a ball.") to build vocabulary. 2. MODELING THE ACTIVITY Start the story with the first picture: "Once upon a time, there was a little cat named Mimi. She woke up early in her cozy bed." Move to the second picture and add: "Mimi jumped out of bed and walked outside to the garden. Write these sentences on the chart paper to show how the story builds. Emphasize: "Each sentence should connect to the picture and the one before it!" 60 3. GROUP PICTURE STORY CHAIN Divide the class into 5 small groups (4-5 students each). Group 1 Group 2 61 Group 3 Group 4 62 Group 5 Give each group a set of the picture cards arranged in order. Instructions for groups: • The first student looks at the first picture and says one sentence. • The next student looks at the second picture and says a sentence that connects to the first. • Continue until all pictures are used and the story has an ending. • One student from each group will share the complete story with the class. Roam around groups to support: Encourage shy students to participate (e.g., "Can you say, ''Mimi found a red ball''?") Help students connect their sentences (e.g., "Great! After Mimi plays with the ball, what happens next?") Write key sentences on sticky notes for each group to display. C. GENERALIZATION Gather the class and have both groups share their stories. Ask: "How did working together help us make the story?" (Expected answer: "We shared ideas, listened to each other, and made a long story together.") Conclude: "Pictures can help us tell stories, and when we work in a chain, we can make amazing stories with our friends!" 63 IV. EVALUATION Formative Assessment: Observe students during the group activity and check if they: Contribute at least one sentence. Speak clearly. Listen to others. Use a simple checklist to record participation and understanding. V. ASSIGNMENT At home, ask students to find 3 simple pictures (from a book or magazine) and make a short story with their family using the picture story chain strategy. They will share their story with the class in the next lesson. VI. REFLECTION (For teacher’s use only: Note which students struggled with speaking/listening, which pictures were most effective, and adjustments for future lessons.) Picture Card Suggestion (Description for Visuals): 1. A small cat lying in a bed with eyes closed. 2. The cat standing by an open door, looking outside. 3. The cat in a garden with green grass and flowers. 4. The cat playing with a red ball. 5. The cat walking back towards the house with the ball. 6. The cat back in bed, sleeping with the ball beside it.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (218,7,NULL,'learn',8,'Additional intervention materials','reference','Use the original additional intervention material with your teacher. Your teacher will record which practice you completed.','36 Additional Intervention Material STORY CHAIN Learning Competency: Retelling a short story. Instructions: A Story Chain is a simple method of passing a story around the class, giving each student plenty of practice in storytelling. Prepare a Story Choose short stories that can be told in 1-3 minutes. You may consider these sample stories suggested. Running the Activity Let the pupils come together in pairs. Each pair is given a short picture story. Give them time to work through it by making their own story about the pictures. At the teachers signal, students A will tell the story to student B. Break up the pair and each child gets a new partner. They take turns in retelling the story they heard from their first partners to the new partner. You can do this several times. At the end you get individuals from the class to recite the last story they heard and then compare it with the original, see if it has improved in the storytelling, see what facts have changed completely and maybe see if the original storyteller can actually recognize their story! Sample stories: Story 1 Mia and the Shiny Stone I have a cat named Mia. It is an orange cat. While playing in the garden, Mia found a shiny blue stone. She found it under the red rose buds. The stone was so smooth and bright that Mia held it gently in her paws. Suddenly, the stone made a tiny ding sound! Mia’s ears perked up. Story 2 Pip the Rabbit and the Wobbly Carrot My father bought me a rabbit. I named him Pip. Pip, is a white rabbit. It dug up a purple carrot. It felt soft and wobbly in his teeth. Pip was about to take a bite but the carrot jiggled on its own! Story 3 Lila the Bird’s Lost Song My sister Jessa has a blue bird that forgot how to sing. It did not cheep. No trills, no sound, just silence. The bird found a tiny paper note under a tree and pecked it. The note made a sweet tinkle sound.

37 Story 4 "The Shell at the Beach" "Yesterday, I walked along the sandy beach and found a small shell. It glowed purple and green in the sun! I held it to my ear and listened to the sound of the sea. I wanted to keep it forever." Story 5 "The Bell on the Playground" "At recess today, I found a tiny brass bell under the slide. When I shook it, it sounded like soft music! I showed it to my friend Leo. Then we took turns ringing it. It was the prettiest sound I’d ever heard." Story 6 "The Feather in the Garden" "One morning, I was watering flowers in the garden. A feather floated down. It was soft and white, and it fluttered in the wind before landing in my hand. I think it came from the big bird in the tree above our house." Unknown word: fluttered (moved lightly up and down) Story 7 "The Toy in My Closet" "I was cleaning my closet and found an old toy car I’d forgotten. When I pushed it, the wheels whirred fast across the floor! It was red and shiny, even after all these years. I couldn’t wait to play with it again." Unknown word: whirred (made a soft, buzzing sound) Story 8 "The Stone in the Forest" "On our walk in the forest, I spotted a smooth stone by the path. It was polished until it looked like glass. It was like the color of the sky. I put it in my pocket to show my mom. My Mom loves pretty rocks." Unknown word: polished (made smooth and shiny) Story 9 "The Butterfly on the Flower" "I sat on the porch and watched a butterfly land on a pink rose. Its wings were orange and black, and it darted from flower to flower. I held my breath so I wouldn’t scare it away. It stayed for five whole minutes!" Unknown word: darted (moved quickly and suddenly) Story 10 "The Note in the Library" "I was looking for a book in the library when I found a note under a shelf. It was scrawled in colorful crayon and said, ‘Meet me at the park!’ I wondered who wrote it—maybe my friend Lila?" Unknown word: scrawled (written quickly and messily)

38 Story 11 "The Leaf on the Bench" "I sat on the park bench and picked up a leaf from the ground. It was crimson—a bright, deep red—like a little fire! I pressed it between two pages of my notebook to keep it safe. It’s my favorite leaf ever." Unknown word: crimson (a dark red color) Story 12 "The Cookie Cutter in the Kitchen" "I was helping mom bake cookies when I found a tiny cookie cutter in the drawer. It had an intricate shape—like a little star with lots of points! We used it to make star cookies, and they tasted so good." Unknown word: intricate (having many small, detailed parts) Story 13 "The Button at the Bus Stop" "While waiting for the bus, I found a button on the ground. It was silver and it glinted in the sunlight. It is like a tiny moon! I showed it to the bus driver. The driver helped me put it in the ‘lost and found’ box." Unknown word: glinted (shone with a quick, bright flash) Additional Intervention Material PICTURE TALK Picture talk activities are engaging ways to enhance children''s communication skills, imagination, and comprehension through discussions bas ed on images. What is a Picture Talk Activity? A picture talk activity involves using images to spark discussions among children. This method encourages kids to observe, analyze, and express their thoughts about the pictures, fostering their communication and literacy skills. It can be adapted to various topics, making it a versatile tool for learning. Steps to Create Picture Talk Activities 1. Choose a Topic: Select a theme that interests the children, such as nature, family, or sports. This helps to engage them more effectively. 2. Select a Picture: Find a picture that aligns with the chosen topic. It should be visually stimulating and rich in details to encourage discussion. 3. Project the Image: Display the picture on a screen or print it out for the children to see. This allows everyone to focus on the same visual stimulus.','assets/module/page-043.jpg','["assets/module/page-043.jpg", "assets/module/page-044.jpg", "assets/module/page-045.jpg"]','36 Additional Intervention Material STORY CHAIN Learning Competency: Retelling a short story. Instructions: A Story Chain is a simple method of passing a story around the class, giving each student plenty of practice in storytelling. Prepare a Story Choose short stories that can be told in 1-3 minutes. You may consider these sample stories suggested. Running the Activity Let the pupils come together in pairs. Each pair is given a short picture story. Give them time to work through it by making their own story about the pictures. At the teachers signal, students A will tell the story to student B. Break up the pair and each child gets a new partner. They take turns in retelling the story they heard from their first partners to the new partner. You can do this several times. At the end you get individuals from the class to recite the last story they heard and then compare it with the original, see if it has improved in the storytelling, see what facts have changed completely and maybe see if the original storyteller can actually recognize their story! Sample stories: Story 1 Mia and the Shiny Stone I have a cat named Mia. It is an orange cat. While playing in the garden, Mia found a shiny blue stone. She found it under the red rose buds. The stone was so smooth and bright that Mia held it gently in her paws. Suddenly, the stone made a tiny ding sound! Mia’s ears perked up. Story 2 Pip the Rabbit and the Wobbly Carrot My father bought me a rabbit. I named him Pip. Pip, is a white rabbit. It dug up a purple carrot. It felt soft and wobbly in his teeth. Pip was about to take a bite but the carrot jiggled on its own! Story 3 Lila the Bird’s Lost Song My sister Jessa has a blue bird that forgot how to sing. It did not cheep. No trills, no sound, just silence. The bird found a tiny paper note under a tree and pecked it. The note made a sweet tinkle sound.

