INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (219,8,NULL,'learn',10,'Teacher-guided lesson checklist','reference','With your teacher, check all lesson procedures, evaluation, and home practice in the official guide. Your teacher confirms completion using the original checklist.','64 LESSON PLAN 8: ORAL LANGUAGE USING PICTURE TALK ACTIVITIES I. OBJECTIVES By the end of the lesson, students will be able to: 1. Describe visible details in a picture using simple words and phrases. 2. Ask and answer basic questions about the picture (who, what, where, when, why). 3. Share a short personal connection to the picture in 1-2 clear sentences. II. SUBJECT MATTER Topic: Oral Language Development through Picture Talk Activities: "See & Say," "Picture Question Circle," "My Connection Share" Materials: 1 large, colorful, detailed picture (e.g., a group of children playing at a park with slides, swings, trees, a dog, and ice cream vendor) Smaller copies of the same picture for each group (optional) Whiteboard or chart paper Marker "Question Cards" (with who/what/where/when/why written on them) Skills: Speaking, listening, observing, questioning Values Integration: Sharing, active listening, appreciating others’ experiences III. . LEARNING PROCEDURE A. MOTIVATION "Mystery Picture Peek:" Hold up the large picture with most of it covered, showing only a small part (e.g., the dog’s tail). Ask: "What do you think this is? What do you think is in the rest of the picture?" Let 3-4 students guess, then reveal the full picture with a big "ta-da!" to build excitement. 65 B. LESSON PROPER 1. ACTIVITY 1: SEE & SAY Display the large picture prominently. Explain: "Let’s play ''See & Say''! Look closely at the picture, and when you see something, stand up and say what it is. For example: ''I see a slide!''" Let students take turns sharing what they notice. As they speak, write key words on the board (e.g., children, park, slide, dog, ice cream). Encourage more details: "Great! What color is the slide?" or "How many children do you see?" Check-in: Point to words on the board and ask students to point to the corresponding item in the picture. 2. ACTIVITY 2: PICTURE QUESTION CIRCLE Have students sit in a large circle. Give out the 5 "Question Cards" to 5 different students. Instructions: 1. The student with the "who" card asks: "Who is in the picture?" Let 2-3 students answer. 2. Pass the card to the next person, then the "what" card holder asks: "What are the children doing?" 3. Continue with "where" ("Where are they?"), "when" ("When do you think this is happening?"), and "why" ("Why do you think they’re happy?"). Model how to ask questions clearly and how to listen before answering. For shy students, offer sentence starters: "I think they’re at..." or "Maybe it’s because..." 3. ACTIVITY 3: "MY CONNECTION SHARE" Explain: "Now, think about a time you did something like what’s in the picture. Can you share 1 or 2 sentences about it?" 66 Model with your own connection: "I remember going to the park with my friend. We played on the swings and ate ice cream!" Let students share in pairs first (to build confidence), then invite 4-5 pairs to share their connections with the class. Praise all contributions: "That’s a wonderful story! I’m glad you had fun at the park too." C. GENERALIZATION Gather students back together and ask: "What did we learn today about pictures?" (Expected answers: "Pictures have many things to see," "We can ask questions about them," "We can tell stories about our own lives from them.") Conclude: "Pictures are like secret doors to talking and sharing stories. You can use any picture to practice speaking!" IV. EVALUATION Formative Assessment: Ask each student to say one thing they saw in the picture or one connection they made. Use a simple smiley face checklist to record if they spoke clearly and participated V. ASSIGNMENT At home, find a picture in a book or on a calendar. Tell your family 3 things you see in it and one time you did something similar. Be ready to share with the class tomorrow! VI. REFLECTION (For teacher’s use only: Note which students struggled with questioning/sharing connections, which parts of the picture sparked the most discussion, and adjustments for future lessons.) Picture Description (for the main visual): A bright, sunny park with green grass and tall trees. Three children (2 girls, 1 boy) are playing – one on the slide, one on the swings, and one petting a brown dog. An ice cream vendor with a colorful cart stands nearby, handing an ice cream cone to a girl. There are blue skies with white clouds, and a bench where a woman is sitting and reading a book.','assets/module/page-072.jpg','["assets/module/page-072.jpg", "assets/module/page-073.jpg", "assets/module/page-074.jpg"]','64 LESSON PLAN 8: ORAL LANGUAGE USING PICTURE TALK ACTIVITIES I. OBJECTIVES By the end of the lesson, students will be able to: 1. Describe visible details in a picture using simple words and phrases. 2. Ask and answer basic questions about the picture (who, what, where, when, why). 3. Share a short personal connection to the picture in 1-2 clear sentences. II. SUBJECT MATTER Topic: Oral Language Development through Picture Talk Activities: "See & Say," "Picture Question Circle," "My Connection Share" Materials: 1 large, colorful, detailed picture (e.g., a group of children playing at a park with slides, swings, trees, a dog, and ice cream vendor) Smaller copies of the same picture for each group (optional) Whiteboard or chart paper Marker "Question Cards" (with who/what/where/when/why written on them) Skills: Speaking, listening, observing, questioning Values Integration: Sharing, active listening, appreciating others’ experiences III. . LEARNING PROCEDURE A. MOTIVATION "Mystery Picture Peek:" Hold up the large picture with most of it covered, showing only a small part (e.g., the dog’s tail). Ask: "What do you think this is? What do you think is in the rest of the picture?" Let 3-4 students guess, then reveal the full picture with a big "ta-da!" to build excitement. 65 B. LESSON PROPER 1. ACTIVITY 1: SEE & SAY Display the large picture prominently. Explain: "Let’s play ''See & Say''! Look closely at the picture, and when you see something, stand up and say what it is. For example: ''I see a slide!''" Let students take turns sharing what they notice. As they speak, write key words on the board (e.g., children, park, slide, dog, ice cream). Encourage more details: "Great! What color is the slide?" or "How many children do you see?" Check-in: Point to words on the board and ask students to point to the corresponding item in the picture. 2. ACTIVITY 2: PICTURE QUESTION CIRCLE Have students sit in a large circle. Give out the 5 "Question Cards" to 5 different students. Instructions: 1. The student with the "who" card asks: "Who is in the picture?" Let 2-3 students answer. 2. Pass the card to the next person, then the "what" card holder asks: "What are the children doing?" 3. Continue with "where" ("Where are they?"), "when" ("When do you think this is happening?"), and "why" ("Why do you think they’re happy?"). Model how to ask questions clearly and how to listen before answering. For shy students, offer sentence starters: "I think they’re at..." or "Maybe it’s because..." 3. ACTIVITY 3: "MY CONNECTION SHARE" Explain: "Now, think about a time you did something like what’s in the picture. Can you share 1 or 2 sentences about it?" 66 Model with your own connection: "I remember going to the park with my friend. We played on the swings and ate ice cream!" Let students share in pairs first (to build confidence), then invite 4-5 pairs to share their connections with the class. Praise all contributions: "That’s a wonderful story! I’m glad you had fun at the park too." C. GENERALIZATION Gather students back together and ask: "What did we learn today about pictures?" (Expected answers: "Pictures have many things to see," "We can ask questions about them," "We can tell stories about our own lives from them.") Conclude: "Pictures are like secret doors to talking and sharing stories. You can use any picture to practice speaking!" IV. EVALUATION Formative Assessment: Ask each student to say one thing they saw in the picture or one connection they made. Use a simple smiley face checklist to record if they spoke clearly and participated V. ASSIGNMENT At home, find a picture in a book or on a calendar. Tell your family 3 things you see in it and one time you did something similar. Be ready to share with the class tomorrow! VI. REFLECTION (For teacher’s use only: Note which students struggled with questioning/sharing connections, which parts of the picture sparked the most discussion, and adjustments for future lessons.) Picture Description (for the main visual): A bright, sunny park with green grass and tall trees. Three children (2 girls, 1 boy) are playing – one on the slide, one on the swings, and one petting a brown dog. An ice cream vendor with a colorful cart stands nearby, handing an ice cream cone to a girl. There are blue skies with white clouds, and a bench where a woman is sitting and reading a book.',NULL,10,72,'64 LESSON PLAN 8: ORAL LANGUAGE USING PICTURE TALK ACTIVITIES I. OBJECTIVES By the end of the lesson, students will be able to: 1. Describe visible details in a picture using simple words and phrases. 2. Ask and answer basic questions about the picture (who, what, where, when, why). 3. Share a short personal connection to the picture in 1-2 clear sentences. II. SUBJECT MATTER Topic: Oral Language Development through Picture Talk Activities: "See & Say," "Picture Question Circle," "My Connection Share" Materials: 1 large, colorful, detailed picture (e.g., a group of children playing at a park with slides, swings, trees, a dog, and ice cream vendor) Smaller copies of the same picture for each group (optional) Whiteboard or chart paper Marker "Question Cards" (with who/what/where/when/why written on them) Skills: Speaking, listening, observing, questioning Values Integration: Sharing, active listening, appreciating others’ experiences III. . LEARNING PROCEDURE A. MOTIVATION "Mystery Picture Peek:" Hold up the large picture with most of it covered, showing only a small part (e.g., the dog’s tail). Ask: "What do you think this is? What do you think is in the rest of the picture?" Let 3-4 students guess, then reveal the full picture with a big "ta-da!" to build excitement. 65 B. LESSON PROPER 1. ACTIVITY 1: SEE & SAY Display the large picture prominently. Explain: "Let’s play ''See & Say''! Look closely at the picture, and when you see something, stand up and say what it is. For example: ''I see a slide!''" Let students take turns sharing what they notice. As they speak, write key words on the board (e.g., children, park, slide, dog, ice cream). Encourage more details: "Great! What color is the slide?" or "How many children do you see?" Check-in: Point to words on the board and ask students to point to the corresponding item in the picture. 2. ACTIVITY 2: PICTURE QUESTION CIRCLE Have students sit in a large circle. Give out the 5 "Question Cards" to 5 different students. Instructions: 1. The student with the "who" card asks: "Who is in the picture?" Let 2-3 students answer. 2. Pass the card to the next person, then the "what" card holder asks: "What are the children doing?" 3. Continue with "where" ("Where are they?"), "when" ("When do you think this is happening?"), and "why" ("Why do you think they’re happy?"). Model how to ask questions clearly and how to listen before answering. For shy students, offer sentence starters: "I think they’re at..." or "Maybe it’s because..." 3. ACTIVITY 3: "MY CONNECTION SHARE" Explain: "Now, think about a time you did something like what’s in the picture. Can you share 1 or 2 sentences about it?" 66 Model with your own connection: "I remember going to the park with my friend. We played on the swings and ate ice cream!" Let students share in pairs first (to build confidence), then invite 4-5 pairs to share their connections with the class. Praise all contributions: "That’s a wonderful story! I’m glad you had fun at the park too." C. GENERALIZATION Gather students back together and ask: "What did we learn today about pictures?" (Expected answers: "Pictures have many things to see," "We can ask questions about them," "We can tell stories about our own lives from them.") Conclude: "Pictures are like secret doors to talking and sharing stories. You can use any picture to practice speaking!" IV. EVALUATION Formative Assessment: Ask each student to say one thing they saw in the picture or one connection they made. Use a simple smiley face checklist to record if they spoke clearly and participated V. ASSIGNMENT At home, find a picture in a book or on a calendar. Tell your family 3 things you see in it and one time you did something similar. Be ready to share with the class tomorrow! VI. REFLECTION (For teacher’s use only: Note which students struggled with questioning/sharing connections, which parts of the picture sparked the most discussion, and adjustments for future lessons.) Picture Description (for the main visual): A bright, sunny park with green grass and tall trees. Three children (2 girls, 1 boy) are playing – one on the slide, one on the swings, and one petting a brown dog. An ice cream vendor with a colorful cart stands nearby, handing an ice cream cone to a girl. There are blue skies with white clouds, and a bench where a woman is sitting and reading a book.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (220,8,NULL,'learn',11,'Additional intervention materials','reference','Use the original additional intervention material with your teacher. Your teacher will record which practice you completed.','38 Story 11 "The Leaf on the Bench" "I sat on the park bench and picked up a leaf from the ground. It was crimson—a bright, deep red—like a little fire! I pressed it between two pages of my notebook to keep it safe. It’s my favorite leaf ever." Unknown word: crimson (a dark red color) Story 12 "The Cookie Cutter in the Kitchen" "I was helping mom bake cookies when I found a tiny cookie cutter in the drawer. It had an intricate shape—like a little star with lots of points! We used it to make star cookies, and they tasted so good." Unknown word: intricate (having many small, detailed parts) Story 13 "The Button at the Bus Stop" "While waiting for the bus, I found a button on the ground. It was silver and it glinted in the sunlight. It is like a tiny moon! I showed it to the bus driver. The driver helped me put it in the ‘lost and found’ box." Unknown word: glinted (shone with a quick, bright flash) Additional Intervention Material PICTURE TALK Picture talk activities are engaging ways to enhance children''s communication skills, imagination, and comprehension through discussions bas ed on images. What is a Picture Talk Activity? A picture talk activity involves using images to spark discussions among children. This method encourages kids to observe, analyze, and express their thoughts about the pictures, fostering their communication and literacy skills. It can be adapted to various topics, making it a versatile tool for learning. Steps to Create Picture Talk Activities 1. Choose a Topic: Select a theme that interests the children, such as nature, family, or sports. This helps to engage them more effectively. 2. Select a Picture: Find a picture that aligns with the chosen topic. It should be visually stimulating and rich in details to encourage discussion. 3. Project the Image: Display the picture on a screen or print it out for the children to see. This allows everyone to focus on the same visual stimulus.','assets/module/page-045.jpg','["assets/module/page-045.jpg"]','38 Story 11 "The Leaf on the Bench" "I sat on the park bench and picked up a leaf from the ground. It was crimson—a bright, deep red—like a little fire! I pressed it between two pages of my notebook to keep it safe. It’s my favorite leaf ever." Unknown word: crimson (a dark red color) Story 12 "The Cookie Cutter in the Kitchen" "I was helping mom bake cookies when I found a tiny cookie cutter in the drawer. It had an intricate shape—like a little star with lots of points! We used it to make star cookies, and they tasted so good." Unknown word: intricate (having many small, detailed parts) Story 13 "The Button at the Bus Stop" "While waiting for the bus, I found a button on the ground. It was silver and it glinted in the sunlight. It is like a tiny moon! I showed it to the bus driver. The driver helped me put it in the ‘lost and found’ box." Unknown word: glinted (shone with a quick, bright flash) Additional Intervention Material PICTURE TALK Picture talk activities are engaging ways to enhance children''s communication skills, imagination, and comprehension through discussions bas ed on images. What is a Picture Talk Activity? A picture talk activity involves using images to spark discussions among children. This method encourages kids to observe, analyze, and express their thoughts about the pictures, fostering their communication and literacy skills. It can be adapted to various topics, making it a versatile tool for learning. Steps to Create Picture Talk Activities 1. Choose a Topic: Select a theme that interests the children, such as nature, family, or sports. This helps to engage them more effectively. 2. Select a Picture: Find a picture that aligns with the chosen topic. It should be visually stimulating and rich in details to encourage discussion. 3. Project the Image: Display the picture on a screen or print it out for the children to see. This allows everyone to focus on the same visual stimulus.',NULL,10,45,'38 Story 11 "The Leaf on the Bench" "I sat on the park bench and picked up a leaf from the ground. It was crimson—a bright, deep red—like a little fire! I pressed it between two pages of my notebook to keep it safe. It’s my favorite leaf ever." Unknown word: crimson (a dark red color) Story 12 "The Cookie Cutter in the Kitchen" "I was helping mom bake cookies when I found a tiny cookie cutter in the drawer. It had an intricate shape—like a little star with lots of points! We used it to make star cookies, and they tasted so good." Unknown word: intricate (having many small, detailed parts) Story 13 "The Button at the Bus Stop" "While waiting for the bus, I found a button on the ground. It was silver and it glinted in the sunlight. It is like a tiny moon! I showed it to the bus driver. The driver helped me put it in the ‘lost and found’ box." Unknown word: glinted (shone with a quick, bright flash) Additional Intervention Material PICTURE TALK Picture talk activities are engaging ways to enhance children''s communication skills, imagination, and comprehension through discussions bas ed on images. What is a Picture Talk Activity? A picture talk activity involves using images to spark discussions among children. This method encourages kids to observe, analyze, and express their thoughts about the pictures, fostering their communication and literacy skills. It can be adapted to various topics, making it a versatile tool for learning. Steps to Create Picture Talk Activities 1. Choose a Topic: Select a theme that interests the children, such as nature, family, or sports. This helps to engage them more effectively. 2. Select a Picture: Find a picture that aligns with the chosen topic. It should be visually stimulating and rich in details to encourage discussion. 3. Project the Image: Display the picture on a screen or print it out for the children to see. This allows everyone to focus on the same visual stimulus.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (221,9,NULL,'learn',8,'Teacher-guided lesson checklist','reference','With your teacher, check all lesson procedures, evaluation, and home practice in the official guide. Your teacher confirms completion using the original checklist.','67 LESSON PLAN 9: RECITE, CLAP & SMILE – “Little Voices Shining Through Poems" I. OBJECTIVES By the end of the lesson, students will be able to: 1. Recite a short, familiar poem or nursery rhyme with a clear, loud voice. 2. Match their tone (happy, silly, soft) to the poem’s feeling. 3. Use simple gestures or actions to go with key words in the poem. 4. Listen respectfully to peers’ recitations and give a positive "thumbs up." II. MATERIALS Picture Poem Pack: Short, colorful poems/nursery rhymes with big images (e.g., "Twinkle, Twinkle, Little Star," "Baa, Baa, Black Sheep," "Five Little Ducks," "The Itsy-Bitsy Spider"). Audio clips of fun, upbeat recitations (with sound effects, e.g., a "quack" for ducks, "twinkle" chimes). Visual "Smile & Shine Recitation” Checklist" (with emojis: = clear voice, = happy tone, = gestures). Simple props (stuffed animals, toy spiders, paper stars, tiny hats) for performances. A "Shining Star" sticker for each student. III. PROCEDURE A. Warm-Up: "Rhyme & Clap Dance" Gather students in a circle. The teacher says a rhyming word pair (e.g., "cat – hat") and claps twice. Students repeat the words and clap back. Add simple dances: "dog – frog" → jump like a frog; "bird – word" → flap wings. Goal: Get them moving, practicing rhymes, and using their voices confidently. 68 B. Motivation The Itsy-Bitsy Spider by Anonymous Itsy bitsy spider climbed up the waterspout. down came the rain and washed the spider out; out came the sun and dried up all the rain; and the itsy-bitsy spider climbed up the spout again. Hold up a picture poem book, "The Itsy-Bitsy Spider" and point to the images. Ask: "Who knows this poem? What does the spider do?" Play a 1-minute audio clip of the poem with a silly, wiggly voice and "spider crawl" sound effects. C. LESSON PROPER "How did the voice sound? Was it happy? Silly?" Explain: "Today, we’ll pick a poem, practice saying it with our best voice, and add dances – just like the audio!" Main Activity: "My Turn to Recite!" (15 minutes) Break into 3 simple, hands-on steps: Step 1: Pick & Explore (5 minutes) Lay out the Picture Poem Pack on tables. Students choose a poem they know or like (based on the pictures). The teacher helps each student point to the words as they say the poem aloud once (to practice reading along with their voice). Example: A student picks "Five Little Ducks" and points to each duck as they count down. Step 2: Practice with a Buddy & Props (7 minutes) Pair students up (buddy up a confident reciter with a quieter one). 69 Give each pair a prop (e.g., stuffed duck for "Five Little Ducks," toy spider for "Itsy Bitsy"). Buddies take turns reciting: Use the Smile & Shine Checklist to remind each other: "Speak loud!" "Smile!" "Add a dance!" Example: For "Twinkle, Twinkle," students hold up paper stars and twirl them in the air when they say "twinkle." Step 3: Polish with the Teacher (3 minutes) The teacher circulates to listen to 1–2 lines from each student, giving quick feedback: "Great job wiggling like a spider!" or "Try speaking a little louder so I can hear you better!" Closure: "Little Voices Showcase" (5 minutes) Invite 4–5 volunteers to recite their poem for the class (or have all pairs share in small "mini-circles" if time is tight). After each recitation, the class gives a positive response: "Thumbs up for [student’s name]!" or a quick clap. Ask 1–2 students: "What was fun about reciting your poem?" (e.g., "Jumping like a duck!") End with a class cheer: "Recite, clap, smile – our little voices shine!" Give every student a "Shining Star" sticker for participating. IV. EVALUATION (Formative) Use the visual Smile & Shine Checklist to observe: Clear, audible voice Tone matches the poem’s feeling (happy, silly, etc.) Simple gestures/actions to support key words Observe participation in the warm-up, buddy practice, and showcase. Check that students listen respectfully to peers.','assets/module/page-075.jpg','["assets/module/page-075.jpg", "assets/module/page-076.jpg", "assets/module/page-077.jpg"]','67 LESSON PLAN 9: RECITE, CLAP & SMILE – “Little Voices Shining Through Poems" I. OBJECTIVES By the end of the lesson, students will be able to: 1. Recite a short, familiar poem or nursery rhyme with a clear, loud voice. 2. Match their tone (happy, silly, soft) to the poem’s feeling. 3. Use simple gestures or actions to go with key words in the poem. 4. Listen respectfully to peers’ recitations and give a positive "thumbs up." II. MATERIALS Picture Poem Pack: Short, colorful poems/nursery rhymes with big images (e.g., "Twinkle, Twinkle, Little Star," "Baa, Baa, Black Sheep," "Five Little Ducks," "The Itsy-Bitsy Spider"). Audio clips of fun, upbeat recitations (with sound effects, e.g., a "quack" for ducks, "twinkle" chimes). Visual "Smile & Shine Recitation” Checklist" (with emojis: = clear voice, = happy tone, = gestures). Simple props (stuffed animals, toy spiders, paper stars, tiny hats) for performances. A "Shining Star" sticker for each student. III. PROCEDURE A. Warm-Up: "Rhyme & Clap Dance" Gather students in a circle. The teacher says a rhyming word pair (e.g., "cat – hat") and claps twice. Students repeat the words and clap back. Add simple dances: "dog – frog" → jump like a frog; "bird – word" → flap wings. Goal: Get them moving, practicing rhymes, and using their voices confidently. 68 B. Motivation The Itsy-Bitsy Spider by Anonymous Itsy bitsy spider climbed up the waterspout. down came the rain and washed the spider out; out came the sun and dried up all the rain; and the itsy-bitsy spider climbed up the spout again. Hold up a picture poem book, "The Itsy-Bitsy Spider" and point to the images. Ask: "Who knows this poem? What does the spider do?" Play a 1-minute audio clip of the poem with a silly, wiggly voice and "spider crawl" sound effects. C. LESSON PROPER "How did the voice sound? Was it happy? Silly?" Explain: "Today, we’ll pick a poem, practice saying it with our best voice, and add dances – just like the audio!" Main Activity: "My Turn to Recite!" (15 minutes) Break into 3 simple, hands-on steps: Step 1: Pick & Explore (5 minutes) Lay out the Picture Poem Pack on tables. Students choose a poem they know or like (based on the pictures). The teacher helps each student point to the words as they say the poem aloud once (to practice reading along with their voice). Example: A student picks "Five Little Ducks" and points to each duck as they count down. Step 2: Practice with a Buddy & Props (7 minutes) Pair students up (buddy up a confident reciter with a quieter one). 69 Give each pair a prop (e.g., stuffed duck for "Five Little Ducks," toy spider for "Itsy Bitsy"). Buddies take turns reciting: Use the Smile & Shine Checklist to remind each other: "Speak loud!" "Smile!" "Add a dance!" Example: For "Twinkle, Twinkle," students hold up paper stars and twirl them in the air when they say "twinkle." Step 3: Polish with the Teacher (3 minutes) The teacher circulates to listen to 1–2 lines from each student, giving quick feedback: "Great job wiggling like a spider!" or "Try speaking a little louder so I can hear you better!" Closure: "Little Voices Showcase" (5 minutes) Invite 4–5 volunteers to recite their poem for the class (or have all pairs share in small "mini-circles" if time is tight). After each recitation, the class gives a positive response: "Thumbs up for [student’s name]!" or a quick clap. Ask 1–2 students: "What was fun about reciting your poem?" (e.g., "Jumping like a duck!") End with a class cheer: "Recite, clap, smile – our little voices shine!" Give every student a "Shining Star" sticker for participating. IV. EVALUATION (Formative) Use the visual Smile & Shine Checklist to observe: Clear, audible voice Tone matches the poem’s feeling (happy, silly, etc.) Simple gestures/actions to support key words Observe participation in the warm-up, buddy practice, and showcase. Check that students listen respectfully to peers.',NULL,10,75,'67 LESSON PLAN 9: RECITE, CLAP & SMILE – “Little Voices Shining Through Poems" I. OBJECTIVES By the end of the lesson, students will be able to: 1. Recite a short, familiar poem or nursery rhyme with a clear, loud voice. 2. Match their tone (happy, silly, soft) to the poem’s feeling. 3. Use simple gestures or actions to go with key words in the poem. 4. Listen respectfully to peers’ recitations and give a positive "thumbs up." II. MATERIALS Picture Poem Pack: Short, colorful poems/nursery rhymes with big images (e.g., "Twinkle, Twinkle, Little Star," "Baa, Baa, Black Sheep," "Five Little Ducks," "The Itsy-Bitsy Spider"). Audio clips of fun, upbeat recitations (with sound effects, e.g., a "quack" for ducks, "twinkle" chimes). Visual "Smile & Shine Recitation” Checklist" (with emojis: = clear voice, = happy tone, = gestures). Simple props (stuffed animals, toy spiders, paper stars, tiny hats) for performances. A "Shining Star" sticker for each student. III. PROCEDURE A. Warm-Up: "Rhyme & Clap Dance" Gather students in a circle. The teacher says a rhyming word pair (e.g., "cat – hat") and claps twice. Students repeat the words and clap back. Add simple dances: "dog – frog" → jump like a frog; "bird – word" → flap wings. Goal: Get them moving, practicing rhymes, and using their voices confidently. 68 B. Motivation The Itsy-Bitsy Spider by Anonymous Itsy bitsy spider climbed up the waterspout. down came the rain and washed the spider out; out came the sun and dried up all the rain; and the itsy-bitsy spider climbed up the spout again. Hold up a picture poem book, "The Itsy-Bitsy Spider" and point to the images. Ask: "Who knows this poem? What does the spider do?" Play a 1-minute audio clip of the poem with a silly, wiggly voice and "spider crawl" sound effects. C. LESSON PROPER "How did the voice sound? Was it happy? Silly?" Explain: "Today, we’ll pick a poem, practice saying it with our best voice, and add dances – just like the audio!" Main Activity: "My Turn to Recite!" (15 minutes) Break into 3 simple, hands-on steps: Step 1: Pick & Explore (5 minutes) Lay out the Picture Poem Pack on tables. Students choose a poem they know or like (based on the pictures). The teacher helps each student point to the words as they say the poem aloud once (to practice reading along with their voice). Example: A student picks "Five Little Ducks" and points to each duck as they count down. Step 2: Practice with a Buddy & Props (7 minutes) Pair students up (buddy up a confident reciter with a quieter one). 69 Give each pair a prop (e.g., stuffed duck for "Five Little Ducks," toy spider for "Itsy Bitsy"). Buddies take turns reciting: Use the Smile & Shine Checklist to remind each other: "Speak loud!" "Smile!" "Add a dance!" Example: For "Twinkle, Twinkle," students hold up paper stars and twirl them in the air when they say "twinkle." Step 3: Polish with the Teacher (3 minutes) The teacher circulates to listen to 1–2 lines from each student, giving quick feedback: "Great job wiggling like a spider!" or "Try speaking a little louder so I can hear you better!" Closure: "Little Voices Showcase" (5 minutes) Invite 4–5 volunteers to recite their poem for the class (or have all pairs share in small "mini-circles" if time is tight). After each recitation, the class gives a positive response: "Thumbs up for [student’s name]!" or a quick clap. Ask 1–2 students: "What was fun about reciting your poem?" (e.g., "Jumping like a duck!") End with a class cheer: "Recite, clap, smile – our little voices shine!" Give every student a "Shining Star" sticker for participating. IV. EVALUATION (Formative) Use the visual Smile & Shine Checklist to observe: Clear, audible voice Tone matches the poem’s feeling (happy, silly, etc.) Simple gestures/actions to support key words Observe participation in the warm-up, buddy practice, and showcase. Check that students listen respectfully to peers.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (222,10,NULL,'learn',7,'Teacher-guided lesson checklist','reference','With your teacher, check all lesson procedures, evaluation, and home practice in the official guide. Your teacher confirms completion using the original checklist.','70 LESSON PLAN 10: TALK, PLAY & SHARE – LITTLE VOICES CONNECTING Communicative Language Teaching (CLT) Strategy I. OBJECTIVES By the end of the lesson, students will be able to: 1. Greet peers and ask simple questions (e.g., "What’s your name?" "What do you have?"). 2. Share personal information about a favorite toy (e.g., "This is my teddy. He’s soft."). 4. Collaborate with a friend to create a short, simple "toy story" using spoken words. 5. Listen respectfully to peers and respond with a simple comment (e.g., "Cool!" "I like it too!"). II. MATERIAL Stuffed toys or toy pictures (one per student; or let students bring their own favorite toy). "Talking Flashcards" with simple questions/responses (e.g., "What’s this?" → "It’s a..."). A "Chat Box" with small items (toy car, doll, ball) for picking prompts. Visual "Talk & Connect Checklist" (emojis: = greet, = ask, = share, = listen). "Friendship Sticker" for each student. III. PROCEDURE 1. Preparatory Activities A. Warm-Up/Motivation: "Hello, Friend! Circle" (5 minutes) Gather students in a circle. The teacher models: "Hi! My name is [Teacher’s name]. How are you, [Student’s name]?" 71 Students take turns greeting the friend next to them, using the same pattern. Add a fun twist: they can wave, high-five, or do a silly dance while greeting. Goal: Practice real, face-to-face interaction and basic greetings. 2. Developmental Activities Introduction: "Our Toys, Our Stories" (5 minutes) Hold up a stuffed toy and say: "This is my bunny. Her name is Floppy. She likes to jump!" Ask: "Who has a toy at home? What’s your toy like?" Let 2–3 students share quickly. 3. Analysis/Discussion Explain: "Today, we’ll talk to our friends about our toys—ask them questions, share stories, and play together with words!" Show the Talk & Connect Checklist and point to each emoji: "These are our super skills for talking today!" 4. Guided Practice Main Activity: "Chat & Play Stations" Divide students into 3 small groups. Rotate stations every 5 minutes (keep it fast-paced for little attention spans!). Station 1: "Toy Show & Tell Chat" Task: Students take turns showing their toy (or picture) and sharing 1–2 things about it (e.g., "This is my car. It goes ‘vroom!’"). Peer Interaction: After each share, friends ask a simple question (using flashcards as a guide): "What color is it?" or "Do you like it?" Why it’s CLT: Real sharing and question-asking about personal things. Station 2: "Find a Toy Match" Task: Students walk around the station with their toy/picture. They ask each other: "Do you have a [car/doll/teddy]?" Goal: Find a friend with the same type of toy. Once they match, they high-five and say: "We both have a [toy]!" Why it’s CLT: Real-world "searching and matching" conversation. 72 Station 3: "Make a Toy Story Together" Task: Pairs pick a toy from the Chat Box. They create a 2-sentence story together (e.g., "This is a ball. The ball bounces to the dog!"). Bonus: Add simple actions (bounce like a ball, bark like a dog) while saying the story. Why it’s CLT: Collaborative communication to create something meaningful. Closure: "Share Our Toy Stories" (5 minutes) Invite 3–4 pairs to share their short toy story with the class. After each story, the class responds with a positive comment: "That’s funny!" or "I love your ball! “Ask 1–2 students: "What was fun about talking to your friend today?" (e.g., "I found a friend with a teddy too!"). End with a class cheer: "Talk, play, share—we’re great at caring and sharing!" Give every student a "Friendship Sticker" for using their talking skills. IV. EVALUATION Use the visual Talk & Connect Checklist to observe: Greets peers appropriately. Asks simple questions. Shares ideas clearly (even if words are simple). Listens when others talk. Note how students interact—do they take turns? Do they respond to their friends’ words? No formal testing—focus on participation and effort to communicate.','assets/module/page-078.jpg','["assets/module/page-078.jpg", "assets/module/page-079.jpg", "assets/module/page-080.jpg"]','70 LESSON PLAN 10: TALK, PLAY & SHARE – LITTLE VOICES CONNECTING Communicative Language Teaching (CLT) Strategy I. OBJECTIVES By the end of the lesson, students will be able to: 1. Greet peers and ask simple questions (e.g., "What’s your name?" "What do you have?"). 2. Share personal information about a favorite toy (e.g., "This is my teddy. He’s soft."). 4. Collaborate with a friend to create a short, simple "toy story" using spoken words. 5. Listen respectfully to peers and respond with a simple comment (e.g., "Cool!" "I like it too!"). II. MATERIAL Stuffed toys or toy pictures (one per student; or let students bring their own favorite toy). "Talking Flashcards" with simple questions/responses (e.g., "What’s this?" → "It’s a..."). A "Chat Box" with small items (toy car, doll, ball) for picking prompts. Visual "Talk & Connect Checklist" (emojis: = greet, = ask, = share, = listen). "Friendship Sticker" for each student. III. PROCEDURE 1. Preparatory Activities A. Warm-Up/Motivation: "Hello, Friend! Circle" (5 minutes) Gather students in a circle. The teacher models: "Hi! My name is [Teacher’s name]. How are you, [Student’s name]?" 71 Students take turns greeting the friend next to them, using the same pattern. Add a fun twist: they can wave, high-five, or do a silly dance while greeting. Goal: Practice real, face-to-face interaction and basic greetings. 2. Developmental Activities Introduction: "Our Toys, Our Stories" (5 minutes) Hold up a stuffed toy and say: "This is my bunny. Her name is Floppy. She likes to jump!" Ask: "Who has a toy at home? What’s your toy like?" Let 2–3 students share quickly. 3. Analysis/Discussion Explain: "Today, we’ll talk to our friends about our toys—ask them questions, share stories, and play together with words!" Show the Talk & Connect Checklist and point to each emoji: "These are our super skills for talking today!" 4. Guided Practice Main Activity: "Chat & Play Stations" Divide students into 3 small groups. Rotate stations every 5 minutes (keep it fast-paced for little attention spans!). Station 1: "Toy Show & Tell Chat" Task: Students take turns showing their toy (or picture) and sharing 1–2 things about it (e.g., "This is my car. It goes ‘vroom!’"). Peer Interaction: After each share, friends ask a simple question (using flashcards as a guide): "What color is it?" or "Do you like it?" Why it’s CLT: Real sharing and question-asking about personal things. Station 2: "Find a Toy Match" Task: Students walk around the station with their toy/picture. They ask each other: "Do you have a [car/doll/teddy]?" Goal: Find a friend with the same type of toy. Once they match, they high-five and say: "We both have a [toy]!" Why it’s CLT: Real-world "searching and matching" conversation. 72 Station 3: "Make a Toy Story Together" Task: Pairs pick a toy from the Chat Box. They create a 2-sentence story together (e.g., "This is a ball. The ball bounces to the dog!"). Bonus: Add simple actions (bounce like a ball, bark like a dog) while saying the story. Why it’s CLT: Collaborative communication to create something meaningful. Closure: "Share Our Toy Stories" (5 minutes) Invite 3–4 pairs to share their short toy story with the class. After each story, the class responds with a positive comment: "That’s funny!" or "I love your ball! “Ask 1–2 students: "What was fun about talking to your friend today?" (e.g., "I found a friend with a teddy too!"). End with a class cheer: "Talk, play, share—we’re great at caring and sharing!" Give every student a "Friendship Sticker" for using their talking skills. IV. EVALUATION Use the visual Talk & Connect Checklist to observe: Greets peers appropriately. Asks simple questions. Shares ideas clearly (even if words are simple). Listens when others talk. Note how students interact—do they take turns? Do they respond to their friends’ words? No formal testing—focus on participation and effort to communicate.',NULL,10,78,'70 LESSON PLAN 10: TALK, PLAY & SHARE – LITTLE VOICES CONNECTING Communicative Language Teaching (CLT) Strategy I. OBJECTIVES By the end of the lesson, students will be able to: 1. Greet peers and ask simple questions (e.g., "What’s your name?" "What do you have?"). 2. Share personal information about a favorite toy (e.g., "This is my teddy. He’s soft."). 4. Collaborate with a friend to create a short, simple "toy story" using spoken words. 5. Listen respectfully to peers and respond with a simple comment (e.g., "Cool!" "I like it too!"). II. MATERIAL Stuffed toys or toy pictures (one per student; or let students bring their own favorite toy). "Talking Flashcards" with simple questions/responses (e.g., "What’s this?" → "It’s a..."). A "Chat Box" with small items (toy car, doll, ball) for picking prompts. Visual "Talk & Connect Checklist" (emojis: = greet, = ask, = share, = listen). "Friendship Sticker" for each student. III. PROCEDURE 1. Preparatory Activities A. Warm-Up/Motivation: "Hello, Friend! Circle" (5 minutes) Gather students in a circle. The teacher models: "Hi! My name is [Teacher’s name]. How are you, [Student’s name]?" 71 Students take turns greeting the friend next to them, using the same pattern. Add a fun twist: they can wave, high-five, or do a silly dance while greeting. Goal: Practice real, face-to-face interaction and basic greetings. 2. Developmental Activities Introduction: "Our Toys, Our Stories" (5 minutes) Hold up a stuffed toy and say: "This is my bunny. Her name is Floppy. She likes to jump!" Ask: "Who has a toy at home? What’s your toy like?" Let 2–3 students share quickly. 3. Analysis/Discussion Explain: "Today, we’ll talk to our friends about our toys—ask them questions, share stories, and play together with words!" Show the Talk & Connect Checklist and point to each emoji: "These are our super skills for talking today!" 4. Guided Practice Main Activity: "Chat & Play Stations" Divide students into 3 small groups. Rotate stations every 5 minutes (keep it fast-paced for little attention spans!). Station 1: "Toy Show & Tell Chat" Task: Students take turns showing their toy (or picture) and sharing 1–2 things about it (e.g., "This is my car. It goes ‘vroom!’"). Peer Interaction: After each share, friends ask a simple question (using flashcards as a guide): "What color is it?" or "Do you like it?" Why it’s CLT: Real sharing and question-asking about personal things. Station 2: "Find a Toy Match" Task: Students walk around the station with their toy/picture. They ask each other: "Do you have a [car/doll/teddy]?" Goal: Find a friend with the same type of toy. Once they match, they high-five and say: "We both have a [toy]!" Why it’s CLT: Real-world "searching and matching" conversation. 72 Station 3: "Make a Toy Story Together" Task: Pairs pick a toy from the Chat Box. They create a 2-sentence story together (e.g., "This is a ball. The ball bounces to the dog!"). Bonus: Add simple actions (bounce like a ball, bark like a dog) while saying the story. Why it’s CLT: Collaborative communication to create something meaningful. Closure: "Share Our Toy Stories" (5 minutes) Invite 3–4 pairs to share their short toy story with the class. After each story, the class responds with a positive comment: "That’s funny!" or "I love your ball! “Ask 1–2 students: "What was fun about talking to your friend today?" (e.g., "I found a friend with a teddy too!"). End with a class cheer: "Talk, play, share—we’re great at caring and sharing!" Give every student a "Friendship Sticker" for using their talking skills. IV. EVALUATION Use the visual Talk & Connect Checklist to observe: Greets peers appropriately. Asks simple questions. Shares ideas clearly (even if words are simple). Listens when others talk. Note how students interact—do they take turns? Do they respond to their friends’ words? No formal testing—focus on participation and effort to communicate.');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (223,11,NULL,'learn',8,'Teacher-guided lesson checklist','reference','With your teacher, check all lesson procedures, evaluation, and home practice in the official guide. Your teacher confirms completion using the original checklist.','73 LESSON PLAN 11: ORAL LANGUAGE – WORD FRIENDS (WORD ASSOCIATION) I. OBJECTIVE At the end of the lesson, the pupils are expected to: 1. Think of words that go together (e.g., “cat” → “milk,” “paws,” “meow”). 2. Find 3 ways words connect: same meaning, opposites, or things that go together. 3. Share their word friends and explain why they connect. II. SUBJECT MATTER Topic: Word Friends (How Words Connect) Materials: Big pictures (cat, cake, park, sun). Toy props (toy cat, ball, small umbrella). Smiley face stickers. Simple chart with examples: Same meaning: “happy” → “glad.” Opposites: “big” → “small.” Things that go together: “bread” → “butter.” III. PROCEDURE 1. Warm-Up: “Word Catch!” (5 minutes) Game: Toss a soft ball. Teacher says a word (e.g., “red”). Student catches the ball and says a word friend (e.g., “apple”). Class claps if it makes sense! 2. Motivation: “Guess My Word Friend!” (5 minutes) Hold up a toy cat. Ask: “What words do you think of? Meow? Milk? Paws?” Say: “Today, we’ll play with word friends—words that love to go together!” 74 3. Activity 1: “Word Friends on the Board” (10 minutes) Step 1: Stick a picture of a cat on the board. Ask: “What words go with cat?” Students shout out (e.g., “milk,” “tail”). Add their words with sticky notes. Step 2: Show how words connect: “Milk” → goes with cat. “Small” → opposite of big. “Happy” → same as glad. 4. Activity 2: “Word Chain Game” (10 minutes) Groups of 4: Sit in circles. Teacher gives a starting word (e.g., “sun”). Each student adds a word friend (e.g., “sun” → “hot” → “ice cream” → “sprinkles”). Use props (e.g., toy umbrella for “rain”) to help them think! 5. Wrap-Up: “Why Word Friends?” (5 minutes) Ask: “Why is ‘cat’ friends with ‘milk’?” (They go together!) “How do word friends help us talk?” (They make stories fun!) Sticker Time: Give everyone a smiley sticker for participating! IV. EVALUATION Observe: Did the student share a word friend? Did they try to explain the connection (even with gestures)? Symbols: = Shared 3+ words and explained. = Shared 1-2 words. = Tried their best! V. HOMEWORK 1. Draw & Tell: Draw a cat or sun and tell your family 2-word friends. 2. Bring a Prop: Bring a small toy or picture of their favorite word friend for show-and-tell next class. 75 TEACHER TIPS Use actions (e.g., meowing for “cat”) to help explain connections. Keep it silly! If a student says “cat → spaceship,” ask, “Why?” and laugh together. Sing a goodbye song: “Bye-bye, word friends, see you soon!”','assets/module/page-081.jpg','["assets/module/page-081.jpg", "assets/module/page-082.jpg", "assets/module/page-083.jpg"]','73 LESSON PLAN 11: ORAL LANGUAGE – WORD FRIENDS (WORD ASSOCIATION) I. OBJECTIVE At the end of the lesson, the pupils are expected to: 1. Think of words that go together (e.g., “cat” → “milk,” “paws,” “meow”). 2. Find 3 ways words connect: same meaning, opposites, or things that go together. 3. Share their word friends and explain why they connect. II. SUBJECT MATTER Topic: Word Friends (How Words Connect) Materials: Big pictures (cat, cake, park, sun). Toy props (toy cat, ball, small umbrella). Smiley face stickers. Simple chart with examples: Same meaning: “happy” → “glad.” Opposites: “big” → “small.” Things that go together: “bread” → “butter.” III. PROCEDURE 1. Warm-Up: “Word Catch!” (5 minutes) Game: Toss a soft ball. Teacher says a word (e.g., “red”). Student catches the ball and says a word friend (e.g., “apple”). Class claps if it makes sense! 2. Motivation: “Guess My Word Friend!” (5 minutes) Hold up a toy cat. Ask: “What words do you think of? Meow? Milk? Paws?” Say: “Today, we’ll play with word friends—words that love to go together!” 74 3. Activity 1: “Word Friends on the Board” (10 minutes) Step 1: Stick a picture of a cat on the board. Ask: “What words go with cat?” Students shout out (e.g., “milk,” “tail”). Add their words with sticky notes. Step 2: Show how words connect: “Milk” → goes with cat. “Small” → opposite of big. “Happy” → same as glad. 4. Activity 2: “Word Chain Game” (10 minutes) Groups of 4: Sit in circles. Teacher gives a starting word (e.g., “sun”). Each student adds a word friend (e.g., “sun” → “hot” → “ice cream” → “sprinkles”). Use props (e.g., toy umbrella for “rain”) to help them think! 5. Wrap-Up: “Why Word Friends?” (5 minutes) Ask: “Why is ‘cat’ friends with ‘milk’?” (They go together!) “How do word friends help us talk?” (They make stories fun!) Sticker Time: Give everyone a smiley sticker for participating! IV. EVALUATION Observe: Did the student share a word friend? Did they try to explain the connection (even with gestures)? Symbols: = Shared 3+ words and explained. = Shared 1-2 words. = Tried their best! V. HOMEWORK 1. Draw & Tell: Draw a cat or sun and tell your family 2-word friends. 2. Bring a Prop: Bring a small toy or picture of their favorite word friend for show-and-tell next class. 75 TEACHER TIPS Use actions (e.g., meowing for “cat”) to help explain connections. Keep it silly! If a student says “cat → spaceship,” ask, “Why?” and laugh together. Sing a goodbye song: “Bye-bye, word friends, see you soon!”',NULL,10,81,'73 LESSON PLAN 11: ORAL LANGUAGE – WORD FRIENDS (WORD ASSOCIATION) I. OBJECTIVE At the end of the lesson, the pupils are expected to: 1. Think of words that go together (e.g., “cat” → “milk,” “paws,” “meow”). 2. Find 3 ways words connect: same meaning, opposites, or things that go together. 3. Share their word friends and explain why they connect. II. SUBJECT MATTER Topic: Word Friends (How Words Connect) Materials: Big pictures (cat, cake, park, sun). Toy props (toy cat, ball, small umbrella). Smiley face stickers. Simple chart with examples: Same meaning: “happy” → “glad.” Opposites: “big” → “small.” Things that go together: “bread” → “butter.” III. PROCEDURE 1. Warm-Up: “Word Catch!” (5 minutes) Game: Toss a soft ball. Teacher says a word (e.g., “red”). Student catches the ball and says a word friend (e.g., “apple”). Class claps if it makes sense! 2. Motivation: “Guess My Word Friend!” (5 minutes) Hold up a toy cat. Ask: “What words do you think of? Meow? Milk? Paws?” Say: “Today, we’ll play with word friends—words that love to go together!” 74 3. Activity 1: “Word Friends on the Board” (10 minutes) Step 1: Stick a picture of a cat on the board. Ask: “What words go with cat?” Students shout out (e.g., “milk,” “tail”). Add their words with sticky notes. Step 2: Show how words connect: “Milk” → goes with cat. “Small” → opposite of big. “Happy” → same as glad. 4. Activity 2: “Word Chain Game” (10 minutes) Groups of 4: Sit in circles. Teacher gives a starting word (e.g., “sun”). Each student adds a word friend (e.g., “sun” → “hot” → “ice cream” → “sprinkles”). Use props (e.g., toy umbrella for “rain”) to help them think! 5. Wrap-Up: “Why Word Friends?” (5 minutes) Ask: “Why is ‘cat’ friends with ‘milk’?” (They go together!) “How do word friends help us talk?” (They make stories fun!) Sticker Time: Give everyone a smiley sticker for participating! IV. EVALUATION Observe: Did the student share a word friend? Did they try to explain the connection (even with gestures)? Symbols: = Shared 3+ words and explained. = Shared 1-2 words. = Tried their best! V. HOMEWORK 1. Draw & Tell: Draw a cat or sun and tell your family 2-word friends. 2. Bring a Prop: Bring a small toy or picture of their favorite word friend for show-and-tell next class. 75 TEACHER TIPS Use actions (e.g., meowing for “cat”) to help explain connections. Keep it silly! If a student says “cat → spaceship,” ask, “Why?” and laugh together. Sing a goodbye song: “Bye-bye, word friends, see you soon!”');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (224,12,NULL,'learn',8,'Teacher-guided lesson checklist','reference','With your teacher, check all lesson procedures, evaluation, and home practice in the official guide. Your teacher confirms completion using the original checklist.','LESSON PLAN 12: ORAL LANGUAGE – FUN WITH TONGUE TWISTERS I. OBJECTIVE At the end of the lesson, the pupils are expected to: 1. Say simple tongue twisters clearly, focusing on sounds like /p/, /b/, and /s/. 2. Practice saying tongue twisters slowly, then faster. II. SUBJECT MATTER Topic: Tongue Twisters for Clear Speaking References: Grade 1 Phonics Activities Materials: Big posters with 3 tongue twisters (with pictures): 1. “Peter Piper picked pickled peppers.” (Picture: Peter and peppers) 2. “Betty Botter bought butter.” (Picture: Betty and butter) 3. “Six snails slide slowly.” (Picture: snails sliding) Sound cards with pictures (e.g., popcorn for /p/, ball for /b/, snake for /s/). “Tongue Twister Stars/Badge” stickers. Thumbs-up chart for group activities. 76 III. PROCEDURE 1. Preparatory Activities A. Warm-Up (5 minutes): Play “Copy the Sound!”: Teacher says: “/p/ like popping popcorn!” (Students mimic popping and say /p/). Repeat with /b/ (bounce like a ball) and /s/ (slither like a snake). B. Motivation (3 minutes): Say: “Let’s play with silly sentences that twist our tongues! Who can say ‘Peter Piper’ fast without mixing up words?” 2. Developmental Activities Introduce Tongue Twisters: Show the poster and read “Peter Piper” slowly. Clap for each word. Point to the /p/ sound card every time you say “p.” Say it faster like a robot! Group Practice: Repeat with “Betty Botter” (/b/ sound) and “Six snails” (/s/ sound). Students take turns saying one line in pairs. 3. Analysis/Discussion Ask: “Why is ‘Peter Piper’ tricky to say?” (They’ll say: “Too many /p/ sounds!”). “How do tongue twisters help us?” (Answer: “They make our mouths strong for clear talking!”). 4. Guided Practice Tongue Twister Game: In small groups, students pick a tongue twister. 77 Say it slowly, then fast. Friends give a thumbs up if they hear the sounds clearly! Add fun: Hop or clap while saying it! IV. EVALUATION Use a simple checklist: Give “Tongue Twister Star” stickers to everyone who tries! Criteria (Great!) (Good!) (Keep Trying!) Says sounds clearly Tries slow and fast Participates with a smile V. AGREEMENT For homework: 1. Practice one tongue twister with your family. 2. Draw a picture of your favorite tongue twister (e.g., Peter Piper or snails). NOTE FOR TEACHER: Keep it playful! Praise effort over perfection. Use lots of movements (clapping, hopping) to make sounds memorable','assets/module/page-083.jpg','["assets/module/page-083.jpg", "assets/module/page-084.jpg", "assets/module/page-085.jpg"]','LESSON PLAN 12: ORAL LANGUAGE – FUN WITH TONGUE TWISTERS I. OBJECTIVE At the end of the lesson, the pupils are expected to: 1. Say simple tongue twisters clearly, focusing on sounds like /p/, /b/, and /s/. 2. Practice saying tongue twisters slowly, then faster. II. SUBJECT MATTER Topic: Tongue Twisters for Clear Speaking References: Grade 1 Phonics Activities Materials: Big posters with 3 tongue twisters (with pictures): 1. “Peter Piper picked pickled peppers.” (Picture: Peter and peppers) 2. “Betty Botter bought butter.” (Picture: Betty and butter) 3. “Six snails slide slowly.” (Picture: snails sliding) Sound cards with pictures (e.g., popcorn for /p/, ball for /b/, snake for /s/). “Tongue Twister Stars/Badge” stickers. Thumbs-up chart for group activities. 76 III. PROCEDURE 1. Preparatory Activities A. Warm-Up (5 minutes): Play “Copy the Sound!”: Teacher says: “/p/ like popping popcorn!” (Students mimic popping and say /p/). Repeat with /b/ (bounce like a ball) and /s/ (slither like a snake). B. Motivation (3 minutes): Say: “Let’s play with silly sentences that twist our tongues! Who can say ‘Peter Piper’ fast without mixing up words?” 2. Developmental Activities Introduce Tongue Twisters: Show the poster and read “Peter Piper” slowly. Clap for each word. Point to the /p/ sound card every time you say “p.” Say it faster like a robot! Group Practice: Repeat with “Betty Botter” (/b/ sound) and “Six snails” (/s/ sound). Students take turns saying one line in pairs. 3. Analysis/Discussion Ask: “Why is ‘Peter Piper’ tricky to say?” (They’ll say: “Too many /p/ sounds!”). “How do tongue twisters help us?” (Answer: “They make our mouths strong for clear talking!”). 4. Guided Practice Tongue Twister Game: In small groups, students pick a tongue twister. 77 Say it slowly, then fast. Friends give a thumbs up if they hear the sounds clearly! Add fun: Hop or clap while saying it! IV. EVALUATION Use a simple checklist: Give “Tongue Twister Star” stickers to everyone who tries! Criteria (Great!) (Good!) (Keep Trying!) Says sounds clearly Tries slow and fast Participates with a smile V. AGREEMENT For homework: 1. Practice one tongue twister with your family. 2. Draw a picture of your favorite tongue twister (e.g., Peter Piper or snails). NOTE FOR TEACHER: Keep it playful! Praise effort over perfection. Use lots of movements (clapping, hopping) to make sounds memorable',NULL,10,83,'LESSON PLAN 12: ORAL LANGUAGE – FUN WITH TONGUE TWISTERS I. OBJECTIVE At the end of the lesson, the pupils are expected to: 1. Say simple tongue twisters clearly, focusing on sounds like /p/, /b/, and /s/. 2. Practice saying tongue twisters slowly, then faster. II. SUBJECT MATTER Topic: Tongue Twisters for Clear Speaking References: Grade 1 Phonics Activities Materials: Big posters with 3 tongue twisters (with pictures): 1. “Peter Piper picked pickled peppers.” (Picture: Peter and peppers) 2. “Betty Botter bought butter.” (Picture: Betty and butter) 3. “Six snails slide slowly.” (Picture: snails sliding) Sound cards with pictures (e.g., popcorn for /p/, ball for /b/, snake for /s/). “Tongue Twister Stars/Badge” stickers. Thumbs-up chart for group activities. 76 III. PROCEDURE 1. Preparatory Activities A. Warm-Up (5 minutes): Play “Copy the Sound!”: Teacher says: “/p/ like popping popcorn!” (Students mimic popping and say /p/). Repeat with /b/ (bounce like a ball) and /s/ (slither like a snake). B. Motivation (3 minutes): Say: “Let’s play with silly sentences that twist our tongues! Who can say ‘Peter Piper’ fast without mixing up words?” 2. Developmental Activities Introduce Tongue Twisters: Show the poster and read “Peter Piper” slowly. Clap for each word. Point to the /p/ sound card every time you say “p.” Say it faster like a robot! Group Practice: Repeat with “Betty Botter” (/b/ sound) and “Six snails” (/s/ sound). Students take turns saying one line in pairs. 3. Analysis/Discussion Ask: “Why is ‘Peter Piper’ tricky to say?” (They’ll say: “Too many /p/ sounds!”). “How do tongue twisters help us?” (Answer: “They make our mouths strong for clear talking!”). 4. Guided Practice Tongue Twister Game: In small groups, students pick a tongue twister. 77 Say it slowly, then fast. Friends give a thumbs up if they hear the sounds clearly! Add fun: Hop or clap while saying it! IV. EVALUATION Use a simple checklist: Give “Tongue Twister Star” stickers to everyone who tries! Criteria (Great!) (Good!) (Keep Trying!) Says sounds clearly Tries slow and fast Participates with a smile V. AGREEMENT For homework: 1. Practice one tongue twister with your family. 2. Draw a picture of your favorite tongue twister (e.g., Peter Piper or snails). NOTE FOR TEACHER: Keep it playful! Praise effort over perfection. Use lots of movements (clapping, hopping) to make sounds memorable');
INSERT INTO activities (id,lesson_id,assessment_id,phase,position,title,type,instructions,prompt,image_path,image_paths,narration,expected_text,xp_reward,source_page,source_excerpt) VALUES (225,12,NULL,'learn',9,'Additional intervention materials','reference','Use the original additional intervention material with your teacher. Your teacher will record which practice you completed.','35 Additional Intervention Material TONGUE TWISTER 1. Sheena leads, Sheila needs. 2. How can a clam cram in a clean cream can? 3. Top chopstick shops stock top chopsticks. 4. Selfish shellfish. 5. I saw a kitten eating chicken in the kitchen. 6. Near an ear, a nearer ear, a nearly eerie ear. 7. Roberta ran rings around the Roman ruins. 8. He threw three free throws. 9. A happy hippo hopped and hiccupped. 10. Toy boat. Toy boat. Toy boat. 11. Smelly shoes and socks shock sisters. 12. Four fine fresh fish for you. 13. Red lorry, yellow lorry (x3) 14. Freshly-fried flying fish. (x3)','assets/module/page-042.jpg','["assets/module/page-042.jpg"]','35 Additional Intervention Material TONGUE TWISTER 1. Sheena leads, Sheila needs. 2. How can a clam cram in a clean cream can? 3. Top chopstick shops stock top chopsticks. 4. Selfish shellfish. 5. I saw a kitten eating chicken in the kitchen. 6. Near an ear, a nearer ear, a nearly eerie ear. 7. Roberta ran rings around the Roman ruins. 8. He threw three free throws. 9. A happy hippo hopped and hiccupped. 10. Toy boat. Toy boat. Toy boat. 11. Smelly shoes and socks shock sisters. 12. Four fine fresh fish for you. 13. Red lorry, yellow lorry (x3) 14. Freshly-fried flying fish. (x3)',NULL,10,42,'35 Additional Intervention Material TONGUE TWISTER 1. Sheena leads, Sheila needs. 2. How can a clam cram in a clean cream can? 3. Top chopstick shops stock top chopsticks. 4. Selfish shellfish. 5. I saw a kitten eating chicken in the kitchen. 6. Near an ear, a nearer ear, a nearly eerie ear. 7. Roberta ran rings around the Roman ruins. 8. He threw three free throws. 9. A happy hippo hopped and hiccupped. 10. Toy boat. Toy boat. Toy boat. 11. Smelly shoes and socks shock sisters. 12. Four fine fresh fish for you. 13. Red lorry, yellow lorry (x3) 14. Freshly-fried flying fish. (x3)');
