LESSON 1: TALKING ABOUT ONE’S SELF AND ONE’S FAMILY

    PRE-TEST (5 items)

    Assesses prior ability to share basic information about oneself and family.

     1. “Tell me your name and age.”

     2. “What is one thing you like to do for fun?”

     3. “Who lives with you at home?”

     4. “Tell me one thing about your mom, dad, or sibling.”

     5. “What is your family’s favorite food to eat together?”

