LESSON 2: FOLLOW ONE-STEP TO TWO-STEP PHYSICAL DIRECTIONS
    PRE-TEST (5 items)

     Assesses prior ability to follow simple physical directions.

     1. “Stand up.” (2-step)

     2. “Walk to the window and point at something blue.” (2-step)

     3. “Pick up the pencil and put it on the table.” (2-step)

     4. “Turn around and clap your hands once.” (2-step)

     5. “Go to the front of the room and wave at me.” (2-step)

