      (e.g., “Ask your younger sister to keep her toys away—what will you say?

    Give at least two instructions”)
    PRE-TEST (5 items)

    Assesses prior ability to phrase simple verbal instructions.

     1. “If you want your friend to pass you a pencil, what will you say?” (1-

     instruction)

     2. “You want your sibling to do something for you. How will you say it?”

