LESSON 4: RECOGNIZE DESCRIBING WORDS

     (color, shape, size, height, weight, length, distance, etc.)

   PRE-TEST (5 items)

    Assesses prior ability to name basic describing words.

     1. “Look at this red apple—what color is it?”

     2. “Look at this big box—what word tells the size of the box?”

     3. “Look at this round ball—what shape is the ball?”

     4. “Look at this tall tree—what word tells us how high it is?”

     5. “Look at this short pencil—what word tells us the length of the object?”


