LESSON 5: TALK ABOUT TOPICS OF INTEREST

      (e.g., “Tell me what you think about this picture”)

    PRE-TEST (5 items)

    Assesses prior ability to share basic thoughts about a topic.

     1. “I’m showing you a picture of a dog—what do you think about it?”

     2. “What is your favorite toy? Tell me one thing you like about it.”

     3. “Look at this picture of a park—what would you do there?”

     4. “What is your favorite cartoon? Tell me why you like it.”

     5. “Look at this picture of ice cream—do you like it? Why or why not?”





