INSERT INTO source_pages VALUES (12,'                                                                     6

LESSON 6: DESCRIBE IT AND I DRAW

    (Show children a picture; they describe it so someone else can draw it)

   PRE-TEST (5 items)

    Assesses prior ability to describe simple pictures in basic terms.

     1. “I’m showing you a picture of a sun—describe it so I can draw it.”

     2. “Describe this picture of a bird—tell me its color and shape.”

     3. “I’m showing you a picture of a house—describe what it looks like.”

     4. “Describe this picture of a flower—tell me its color and how many petals it

     has.”

     5. “Look at the picture of a car—describe its shape and color.”




