  LESSON 6: DESCRIBE AND DRAW

   (Show children a picture; they will describe it so someone else can draw it)

   POST-TEST (5 items)

   Assesses ability to describe with details so listener can draw accurately.

    1. “I’m showing you a picture of a cat sitting on a chair—describe it: color of

    the cat, shape of the chair, where the cat is sitting.”

    2. “Describe this picture of a tree with apples—tell me the tree’s color, how

   many apples, and if the apples are big or small.”

    3. “I’m showing you a picture of a boy playing with a ball—describe the boy’s

    clothes, the ball’s color, and what he’s doing.”

    4. “Describe this picture of a book on a table—tell me the book’s color, the

    table’s shape, and where the book is on the table.”

    5. “I’m showing you a picture of a rainbow over a lake—describe the colors of

    the rainbow, the lake’s color, and where the rainbow is.”
