INSERT INTO source_pages VALUES (95,'                                                          86



LESSON 12: USING WORD ASOCIATION

POST-TEST (5 items)

Assesses ability to think of multiple related words and explain connections

1. “I say ‘dog’—tell me two words related to ‘dog’ and explain why (e.g., ‘bone’

because dogs like bones).”

2. “I say ‘school’—tell me three words that go with ‘school’.”

3. “I say ‘rain’—tell me two words related to ‘rain’ and say what they have to

do with rain.”

4. “I say ‘toy’—tell me three words that make you think of ‘toy’.”

5. “I say ‘food’—tell me two words related to ‘food’ and explain why.”','assets/module/page-095.jpg','[{"path": "assets/module/image-12.jpeg", "bbox": [27.100000381469727, 768.5499877929688, 586.1099853515625, 825.5], "xref": 12, "width": 2079, "height": 158}]');
INSERT INTO content_issues(description) VALUES ('Printed post-tests on PDF pages 94–95 reverse Lessons 11 and 12 compared with the lesson plans and pre-tests. They are linked by competency: Word Association → Lesson 11; Tongue Twisters → Lesson 12. The original headings remain visible.');
INSERT INTO content_issues(description) VALUES ('Lesson 2 pre-test calls ‘Stand up’ a two-step direction. Preserved verbatim; teacher judges the actual action.');
INSERT INTO content_issues(description) VALUES ('The additional asking-questions game mentions both 20 and 10 questions. Both instructions are preserved; teacher selects the intended stopping rule.');
INSERT INTO content_issues(description) VALUES ('Most answers are personal responses, actions, drawings, or collaborative speech. No fixed correct answers are invented. Teacher observation and official rubrics determine completion.');
INSERT INTO content_issues(description) VALUES ('Some lesson-plan example objects/pictures are requested teaching props, not supplied as separate assets. Teachers supply those objects; unrelated images are not substituted.');
